  mkdir -p "$APP_DIR/core-backend/src"
  cat > "$APP_DIR/core-backend/src/dbMaintenance.ts" << '__COREGSM_EOF__'
/**
 * Keeps the SQLite file healthy without anybody looking at it:
 *  - every 15 minutes the write-ahead log is folded back into the database and truncated, so the -wal file does not grow
 *    for weeks next to a busy poller (it is only checkpointed automatically while no reader holds it back);
 *  - every 6 hours (and once shortly after the start) `PRAGMA optimize` refreshes the planner statistics.
 * Both are cheap and never lock readers for long. A full VACUUM is left out on purpose: it rewrites the file under an
 * exclusive lock; `coregsm backup` and the migrations already make consistent copies with VACUUM INTO.
 */
import { db } from './db.js';
import { log } from './logger.js';

export interface MaintenanceResult {
  /** frames the checkpoint wrote; null when the checkpoint could not run */
  checkpointed: number | null;
  /** the checkpoint did not finish because a reader was still using the log */
  busy: boolean;
}

export function checkpointWal(): MaintenanceResult {
  try {
    const r = db.pragma('wal_checkpoint(TRUNCATE)') as { busy: number; checkpointed: number }[];
    return { checkpointed: r[0]?.checkpointed ?? 0, busy: !!r[0]?.busy };
  } catch (e) {
    log.error('wal checkpoint failed', (e as Error).message);
    return { checkpointed: null, busy: false };
  }
}

export function optimizeDb(): boolean {
  try {
    db.pragma('optimize');
    return true;
  } catch (e) {
    log.error('db optimize failed', (e as Error).message);
    return false;
  }
}

export function startDbMaintenance(): void {
  setInterval(checkpointWal, 15 * 60_000).unref();
  setInterval(optimizeDb, 6 * 3600_000).unref();
  setTimeout(optimizeDb, 60_000).unref();
}
__COREGSM_EOF__
  mkdir -p "$APP_DIR/core-backend/src"
  cat > "$APP_DIR/core-backend/src/deliveries.ts" << '__COREGSM_EOF__'
/**
 * Delivery ledger and queue for everything the Discord bot has to send.
 *
 *   kind 'alert' | 'dm'   -> this table IS the queue (the bot polls /internal/deliveries/pending)
 *   kind 'news' | 'status' -> the table is a ledger: the queue stays in its own table (news), and every
 *                             attempt is mirrored here so the administrator sees attempts and errors in one place
 *
 * Row life: pending (never tried) -> sending (claimed by the bot) -> sent
 *                                  -> error (failed, a retry is scheduled at next_try_at) -> ... -> dead
 * Backoff after the n-th failed attempt: 30 s, 1, 2, 5, 15 min (15 min from then on); after 8 attempts the row is dead.
 * A dead row can be retried by an administrator (POST /api/deliveries/:id/retry).
 */
import type { Express, RequestHandler } from 'express';
import { z } from 'zod';
import { db } from './db.js';

export type DeliveryKind = 'news' | 'alert' | 'dm' | 'status' | 'webhook' | 'email';
export type DeliveryStatus = 'pending' | 'sending' | 'sent' | 'error' | 'dead';

export const BACKOFF_MS = [30_000, 60_000, 120_000, 300_000, 900_000] as const;
export const MAX_ATTEMPTS = 8;
/** a claimed delivery that was never reported is handed out again after this long */
const CLAIM_TIMEOUT_MS = 2 * 60_000;

db.exec(`
CREATE TABLE IF NOT EXISTS deliveries (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  kind TEXT NOT NULL,
  ref_id INTEGER,
  target TEXT NOT NULL DEFAULT '',
  payload TEXT NOT NULL DEFAULT '{}',
  status TEXT NOT NULL DEFAULT 'pending',
  attempts INTEGER NOT NULL DEFAULT 0,
  next_try_at INTEGER NOT NULL DEFAULT 0,
  last_error TEXT,
  created_at INTEGER NOT NULL,
  sent_at INTEGER,
  claimed_at INTEGER
);
CREATE INDEX IF NOT EXISTS idx_deliveries_due ON deliveries(status, next_try_at);
CREATE INDEX IF NOT EXISTS idx_deliveries_ref ON deliveries(kind, ref_id);
`);

/** Delay before the next try after `attempts` failed attempts (1-based). */
export function backoffMs(attempts: number): number {
  const i = Math.min(Math.max(1, Math.floor(attempts)), BACKOFF_MS.length) - 1;
  return BACKOFF_MS[i]!;
}

export interface FailurePlan {
  status: 'error' | 'dead';
  attempts: number;
  /** null when dead */
  nextTryAt: number | null;
}

/**
 * Pure: what happens to a delivery that has just failed.
 * `final` (e.g. the user closed their DMs) gives up at once; `retryAfterMs` (Discord 429) stretches the delay.
 */
export function planFailure(previousAttempts: number, now: number, opts: { final?: boolean; retryAfterMs?: number } = {}): FailurePlan {
  const attempts = previousAttempts + 1;
  if (opts.final || attempts >= MAX_ATTEMPTS) return { status: 'dead', attempts, nextTryAt: null };
  const delay = Math.max(backoffMs(attempts), Math.min(Math.max(0, opts.retryAfterMs ?? 0), 3600_000));
  return { status: 'error', attempts, nextTryAt: now + delay };
}

export interface KindHooks {
  /** a delivery of this kind changed state (pending/sending/sent/error/dead) */
  onState?: (refId: number, status: DeliveryStatus, error: string | null, now: number) => void;
  /** the administrator asked for a manual retry; `payload` is what the ledger row stored */
  retry?: (refId: number, payload: Record<string, unknown>) => void;
}
const hooks = new Map<DeliveryKind, KindHooks>();
export function registerKind(kind: DeliveryKind, h: KindHooks): void {
  hooks.set(kind, h);
}

interface Row {
  id: number;
  kind: DeliveryKind;
  ref_id: number | null;
  target: string;
  payload: string;
  status: DeliveryStatus;
  attempts: number;
  next_try_at: number;
  last_error: string | null;
  created_at: number;
  sent_at: number | null;
}

function prune(now: number): void {
  db.prepare("DELETE FROM deliveries WHERE status = 'sent' AND created_at < ?").run(now - 7 * 86400_000);
  db.prepare("DELETE FROM deliveries WHERE created_at < ?").run(now - 30 * 86400_000);
}

/** Adds a delivery to the queue (alert, dm, status). */
export function enqueueDelivery(d: { kind: DeliveryKind; refId?: number | null; target: string; payload: unknown; delayMs?: number }): number {
  const now = Date.now();
  const r = db
    .prepare('INSERT INTO deliveries (kind, ref_id, target, payload, status, next_try_at, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)')
    .run(d.kind, d.refId ?? null, d.target, JSON.stringify(d.payload ?? {}), 'pending', now + (d.delayMs ?? 0), now);
  prune(now);
  return Number(r.lastInsertRowid);
}

/** Hands the due deliveries of the given kinds to the bot and marks them as being sent. */
export function claimDue(kinds: DeliveryKind[], now = Date.now(), limit = 25): { id: number; kind: DeliveryKind; refId: number | null; target: string; payload: unknown }[] {
  if (!kinds.length) return [];
  const ph = kinds.map(() => '?').join(',');
  const rows = db
    .prepare(
      `SELECT * FROM deliveries WHERE kind IN (${ph})
         AND ((status IN ('pending','error') AND next_try_at <= ?) OR (status = 'sending' AND claimed_at < ?))
       ORDER BY id LIMIT ?`,
    )
    .all(...kinds, now, now - CLAIM_TIMEOUT_MS, limit) as Row[];
  const claim = db.prepare("UPDATE deliveries SET status = 'sending', claimed_at = ? WHERE id = ?");
  return rows.map((r) => {
    claim.run(now, r.id);
    if (r.ref_id !== null) hooks.get(r.kind)?.onState?.(r.ref_id, 'sending', r.last_error, now);
    return { id: r.id, kind: r.kind, refId: r.ref_id, target: r.target, payload: JSON.parse(r.payload) as unknown };
  });
}

/** The bot's verdict on a queued delivery. */
export function reportResult(id: number, res: { ok: true } | { ok: false; error: string; final?: boolean; retryAfterMs?: number }, now = Date.now()): boolean {
  const r = db.prepare('SELECT * FROM deliveries WHERE id = ?').get(id) as Row | undefined;
  if (!r) return false;
  let status: DeliveryStatus;
  let error: string | null = null;
  if (res.ok) {
    status = 'sent';
    db.prepare("UPDATE deliveries SET status = 'sent', attempts = attempts + 1, sent_at = ?, last_error = NULL, claimed_at = NULL WHERE id = ?").run(now, id);
  } else {
    const plan = planFailure(r.attempts, now, res);
    status = plan.status;
    error = res.error.slice(0, 300);
    db.prepare('UPDATE deliveries SET status = ?, attempts = ?, next_try_at = ?, last_error = ?, claimed_at = NULL WHERE id = ?').run(plan.status, plan.attempts, plan.nextTryAt ?? 0, error, id);
  }
  if (r.ref_id !== null) hooks.get(r.kind)?.onState?.(r.ref_id, status, error, now);
  return true;
}

/**
 * Ledger entry for a queue that lives elsewhere (news): one row per (kind, ref_id), updated on every attempt.
 */
export function ledgerRecord(e: {
  kind: DeliveryKind;
  refId: number;
  target: string;
  status: DeliveryStatus;
  attempts: number;
  error?: string | null;
  nextTryAt?: number | null;
  payload?: Record<string, unknown>;
  now?: number;
}): void {
  const now = e.now ?? Date.now();
  const open = db.prepare('SELECT id FROM deliveries WHERE kind = ? AND ref_id = ? ORDER BY id DESC LIMIT 1').get(e.kind, e.refId) as { id: number } | undefined;
  const sentAt = e.status === 'sent' ? now : null;
  if (open) {
    db.prepare('UPDATE deliveries SET status = ?, attempts = ?, next_try_at = ?, last_error = ?, sent_at = COALESCE(?, sent_at), payload = COALESCE(?, payload), target = ? WHERE id = ?').run(
      e.status,
      e.attempts,
      e.nextTryAt ?? 0,
      e.error ?? null,
      sentAt,
      e.payload ? JSON.stringify(e.payload) : null,
      e.target,
      open.id,
    );
  } else {
    db.prepare('INSERT INTO deliveries (kind, ref_id, target, payload, status, attempts, next_try_at, last_error, created_at, sent_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)').run(
      e.kind,
      e.refId,
      e.target,
      JSON.stringify(e.payload ?? {}),
      e.status,
      e.attempts,
      e.nextTryAt ?? 0,
      e.error ?? null,
      now,
      sentAt,
    );
    prune(now);
  }
}

function summary(r: Row): string {
  try {
    const p = JSON.parse(r.payload) as { summary?: string; content?: string; embed?: { title?: string } };
    return String(p.summary ?? p.embed?.title ?? p.content ?? '').slice(0, 120);
  } catch {
    return '';
  }
}

export function registerDeliveries(deps: { app: Express; admin: RequestHandler; internal: RequestHandler }): void {
  const { app, admin, internal } = deps;
  const KINDS = ['news', 'alert', 'dm', 'status', 'webhook', 'email'] as const;
  const STATUSES = ['pending', 'sending', 'sent', 'error', 'dead'] as const;

  app.get('/api/deliveries', admin, (req, res) => {
    const q = z
      .object({
        // an empty value means «no filter»: the panel used to send ?status=&kind=
        status: z.preprocess((v) => (v === '' ? undefined : v), z.enum(STATUSES).optional()),
        kind: z.preprocess((v) => (v === '' ? undefined : v), z.enum(KINDS).optional()),
        limit: z.coerce.number().int().min(1).max(500).optional(),
      })
      .safeParse(req.query);
    if (!q.success) return res.status(400).json({ error: 'Проверьте параметры фильтра' });
    const where: string[] = [];
    const args: (string | number)[] = [];
    if (q.data.status) (where.push('status = ?'), args.push(q.data.status));
    if (q.data.kind) (where.push('kind = ?'), args.push(q.data.kind));
    const rows = db
      .prepare(`SELECT * FROM deliveries ${where.length ? 'WHERE ' + where.join(' AND ') : ''} ORDER BY id DESC LIMIT ?`)
      .all(...args, q.data.limit ?? 100) as Row[];
    const counts: Record<string, number> = { pending: 0, sending: 0, sent: 0, error: 0, dead: 0 };
    for (const c of db.prepare('SELECT status, COUNT(*) AS n FROM deliveries GROUP BY status').all() as { status: string; n: number }[]) counts[c.status] = c.n;
    res.json({
      counts,
      items: rows.map((r) => ({
        id: r.id,
        kind: r.kind,
        refId: r.ref_id,
        target: r.target,
        status: r.status,
        attempts: r.attempts,
        nextTryAt: r.status === 'error' || r.status === 'pending' ? r.next_try_at || null : null,
        lastError: r.last_error,
        createdAt: r.created_at,
        sentAt: r.sent_at,
        summary: summary(r),
      })),
    });
  });

  app.post('/api/deliveries/:id/retry', admin, (req, res) => {
    const id = Number(req.params.id);
    const r = db.prepare('SELECT * FROM deliveries WHERE id = ?').get(id) as Row | undefined;
    if (!r) return res.status(404).json({ error: 'Доставка не найдена' });
    if (r.status !== 'dead' && r.status !== 'error') return res.status(409).json({ error: 'Повторить можно только неудавшуюся доставку' });
    const now = Date.now();
    db.prepare("UPDATE deliveries SET status = 'pending', attempts = 0, next_try_at = ?, last_error = NULL, claimed_at = NULL WHERE id = ?").run(now, id);
    if (r.ref_id !== null) {
      let payload: Record<string, unknown> = {};
      try {
        payload = JSON.parse(r.payload) as Record<string, unknown>;
      } catch {
        /* ledger payload is informational */
      }
      const h = hooks.get(r.kind);
      h?.retry?.(r.ref_id, payload);
      h?.onState?.(r.ref_id, 'pending', null, now);
    }
    res.json({ ok: true, id, status: 'pending' });
  });

  // ----- the bot -----
  app.get('/internal/deliveries/pending', internal, (req, res) => {
    const wanted = String(req.query.kinds ?? 'alert,dm,status')
      .split(',')
      .filter((k): k is 'alert' | 'dm' | 'status' => k === 'alert' || k === 'dm' || k === 'status');
    res.json(claimDue(wanted));
  });

  app.patch('/internal/deliveries/:id', internal, (req, res) => {
    const b = z
      .object({
        ok: z.boolean().optional(),
        status: z.enum(['sent', 'error']).optional(),
        error: z.string().max(300).nullable().optional(),
        final: z.boolean().optional(),
        retryAfterMs: z.number().int().min(0).max(3600_000).optional(),
      })
      .safeParse(req.body);
    if (!b.success) return res.status(400).json({ error: 'bad body' });
    const ok = b.data.ok ?? b.data.status === 'sent';
    const done = reportResult(Number(req.params.id), ok ? { ok: true } : { ok: false, error: b.data.error ?? 'Ошибка отправки', final: b.data.final, retryAfterMs: b.data.retryAfterMs });
    if (!done) return res.status(404).json({ error: 'not found' });
    res.json({ ok: true });
  });
}
__COREGSM_EOF__
  mkdir -p "$APP_DIR/core-backend/src"
  cat > "$APP_DIR/core-backend/src/digest.ts" << '__COREGSM_EOF__'
/**
 * Weekly digest: once a week (the weekday and hour of the panel's time zone are set in the panel) the bot posts a
 * summary of the last seven days to the alerts channel or a channel of its own: players, peak, hours played,
 * availability and outages of every server, the top players, and the change against the week before. The picture
 * is drawn here (skia, like the server cards) and served at a signed address so that Discord can fetch it even
 * when the panel is private.
 */
import crypto from 'node:crypto';
import skia from 'skia-canvas';
import type { Express, RequestHandler } from 'express';
import { z } from 'zod';
import { alertSettings, enqueueAlert } from './alerts.js';
import { JWT_SECRET } from './config.js';
import { db, EFFECTIVE_NAME, getSetting, setSetting } from './db.js';
import { SERVER_ORDER } from './serverData.js';
import { incidentsSince } from './incidents.js';
import { avatarColor, initialOf } from './cardLogic.js';
import { busiestDay, changePct, dailyPeaks, sparkPoints, splitServers, stripCommonPrefix, trendText, uptimeBar, weekEvents, type WeekEvent, wrapName } from './digestLogic.js';
import { localParts } from './localTime.js';
import { brand, publicBase } from './site.js';
import { param } from './http.js';
import { log } from './logger.js';

const { Canvas } = skia;
const DAY = 86_400_000;
const WEEK = 7 * DAY;

export const digestSettings = () => ({
  enabled: getSetting('digest_enabled') === '1',
  channelId: getSetting('digest_channel') ?? '',
  weekday: Math.min(6, Math.max(0, Number(getSetting('digest_weekday') ?? 0) || 0)), // 0 = Monday
  hour: Math.min(23, Math.max(0, Number(getSetting('digest_hour') ?? 10) || 0)),
  lastSent: Number(getSetting('digest_last_sent')) || 0,
  theme: (getSetting('digest_theme') === 'light' ? 'light' : 'dark') as DigestTheme,
});

const tz = () => getSetting('timezone') || process.env.TZ || 'Europe/Moscow';

export interface DigestServer {
  id: number; name: string; game: string; players: number; prevPlayers: number; peak: number; peakAt: number | null;
  hours: number; uptime: number | null; incidents: number; downMinutes: number;
  /** the highest online of each of the seven days (oldest first), for the small chart in the picture */
  daily: number[];
}
export interface Digest {
  from: number; to: number;
  totals: { players: number; prevPlayers: number; peak: number; peakAt: number | null; peakServer: string | null; hours: number; prevHours: number; uptime: number | null; incidents: number; newPlayers: number };
  days: { day: string; players: number }[];
  servers: DigestServer[];
  top: { name: string; hours: number }[];
  /** up to three lines under the picture: the record, the longest outage, new players */
  events: WeekEvent[];
}

/** the summary of the seven days that end at `to` */
export function buildDigest(to = Date.now()): Digest {
  const from = to - WEEK;
  const prevFrom = from - WEEK;
  const servers = db.prepare(`SELECT s.id, ${EFFECTIVE_NAME} AS name, s.game FROM servers s LEFT JOIN status st ON st.server_id = s.id ORDER BY ${SERVER_ORDER}`).all() as { id: number; name: string; game: string }[];
  const visits = db
    .prepare('SELECT server_id AS s, ulower(name) AS k, name, joined_at AS j, COALESCE(left_at, ?) AS l FROM player_sessions WHERE COALESCE(left_at, ?) > ? AND joined_at < ?')
    .all(to, to, prevFrom, to) as { s: number; k: string; name: string; j: number; l: number }[];
  const firstSeen = new Map((db.prepare('SELECT ulower(name) AS k, MIN(joined_at) AS t FROM player_sessions GROUP BY k').all() as { k: string; t: number }[]).map((r) => [r.k, r.t]));
  const clip = (j: number, l: number, a: number, b: number) => Math.max(0, Math.min(l, b) - Math.max(j, a)) / 3600_000;
  const incidents = incidentsSince(from, undefined, to).filter((i) => !i.planned);
  const tzName = tz();
  const days = Array.from({ length: 7 }, (_, i) => localParts(from + (i + 0.5) * DAY, tzName).day);
  const dayOf = (ts: number) => localParts(ts, tzName).day;
  const hist = db.prepare('SELECT ts, players FROM history WHERE server_id = ? AND ts > ? AND ts <= ?');

  const perServer: DigestServer[] = servers.map((sv) => {
    const mine = visits.filter((v) => v.s === sv.id);
    const cur = mine.filter((v) => v.l > from);
    const prev = mine.filter((v) => v.j < from);
    const peak = db.prepare('SELECT players, ts FROM history WHERE server_id = ? AND ts > ? AND ts <= ? ORDER BY players DESC, ts DESC LIMIT 1').get(sv.id, from, to) as { players: number; ts: number } | undefined;
    const up = db.prepare('SELECT SUM(up) AS u, SUM(total) AS t FROM uptime_daily WHERE server_id = ? AND day >= ?').get(sv.id, new Date(from).toISOString().slice(0, 10)) as { u: number | null; t: number | null };
    const inc = incidents.filter((i) => i.serverId === sv.id);
    return {
      id: sv.id,
      name: sv.name,
      game: sv.game,
      players: new Set(cur.map((v) => v.k)).size,
      prevPlayers: new Set(prev.map((v) => v.k)).size,
      peak: peak?.players ?? 0,
      peakAt: peak?.ts ?? null,
      hours: Math.round(cur.reduce((n, v) => n + clip(v.j, v.l, from, to), 0)),
      uptime: up.t ? Math.round((up.u! / up.t) * 1000) / 10 : null,
      incidents: inc.length,
      daily: dailyPeaks(hist.all(sv.id, from, to) as { ts: number; players: number }[], days, dayOf),
      downMinutes: inc.reduce((n, i) => n + Math.round((Math.min(i.end ?? to, to) - Math.max(i.start, from)) / 60_000), 0),
    };
  });

  const cur = visits.filter((v) => v.l > from);
  const prev = visits.filter((v) => v.j < from);
  const byDay = new Map(days.map((d) => [d, new Set<string>()]));
  for (const v of cur) byDay.get(localParts(Math.max(v.j, from), tzName).day)?.add(v.k);
  const per = new Map<string, { name: string; hours: number }>();
  for (const v of cur) {
    const p = per.get(v.k) ?? { name: v.name, hours: 0 };
    p.hours += clip(v.j, v.l, from, to);
    per.set(v.k, p);
  }
  const best = [...perServer].sort((a, b) => b.peak - a.peak)[0];
  const ups = perServer.map((s) => s.uptime).filter((v): v is number => v != null);
  return {
    from,
    to,
    totals: {
      players: new Set(cur.map((v) => v.k)).size,
      prevPlayers: new Set(prev.map((v) => v.k)).size,
      peak: best?.peak ?? 0,
      peakAt: best?.peakAt ?? null,
      peakServer: best && best.peak > 0 ? best.name : null,
      hours: Math.round(cur.reduce((n, v) => n + clip(v.j, v.l, from, to), 0)),
      prevHours: Math.round(prev.reduce((n, v) => n + clip(v.j, v.l, prevFrom, from), 0)),
      uptime: ups.length ? Math.round((ups.reduce((a, b) => a + b, 0) / ups.length) * 10) / 10 : null,
      incidents: incidents.length,
      newPlayers: new Set(cur.filter((v) => (firstSeen.get(v.k) ?? 0) > from).map((v) => v.k)).size,
    },
    days: days.map((day) => ({ day, players: byDay.get(day)?.size ?? 0 })),
    servers: perServer,
    events: weekEvents({
      peak: best?.peak ?? 0,
      peakWhen: best?.peakAt ? new Date(best.peakAt).toLocaleString('ru-RU', { weekday: 'short', hour: '2-digit', minute: '2-digit', timeZone: tzName }).replace(',', '') : '',
      worst: (() => {
        const w = [...incidents].sort((a, b) => b.minutes - a.minutes)[0];
        return w ? { minutes: w.minutes, server: servers.find((x) => x.id === w.serverId)?.name ?? '' } : null;
      })(),
      newPlayers: new Set(cur.filter((v) => (firstSeen.get(v.k) ?? 0) > from).map((v) => v.k)).size,
    }),
    top: [...per.values()].sort((a, b) => b.hours - a.hours).slice(0, 5).map((p) => ({ name: p.name, hours: Math.round(p.hours * 10) / 10 })),
  };
}

const delta = changePct;
const deltaText = (d: number | null) => (d == null ? '' : d === 0 ? ' (как неделей раньше)' : ` (${d > 0 ? '+' : '−'}${Math.abs(d)}% к прошлой неделе)`);
const dateRu = (t: number) => new Date(t).toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', timeZone: tz() });

// ---------- the picture ----------

export type DigestTheme = 'dark' | 'light';
const PALETTES: Record<DigestTheme, { bgA: string; bgB: string; ink: string; ink2: string; ink3: string; ink4: string; card: string; ok: string; bad: string; warn: string; glow: string }> = {
  dark: { bgA: '#15122b', bgB: '#0b0a16', ink: '#ffffff', ink2: 'rgba(255,255,255,.75)', ink3: 'rgba(255,255,255,.6)', ink4: 'rgba(255,255,255,.45)', card: 'rgba(255,255,255,.07)', ok: '#7ee2a8', bad: '#ff8a8a', warn: '#ffd27a', glow: '88' },
  light: { bgA: '#f7f5ff', bgB: '#e6e3f6', ink: '#17142b', ink2: 'rgba(23,20,43,.78)', ink3: 'rgba(23,20,43,.62)', ink4: 'rgba(23,20,43,.5)', card: 'rgba(23,20,43,.06)', ok: '#0f7a52', bad: '#c0392b', warn: '#946200', glow: '33' },
};

const SANS = '"DejaVu Sans", "Liberation Sans", sans-serif';

/* eslint-disable @typescript-eslint/no-explicit-any */
/** the text cut with «…» so that it fits `max` pixels */
function fitText(ctx: any, text: string, max: number): string {
  let t = text;
  while (t.length > 3 && ctx.measureText(t).width > max) t = `${t.slice(0, -2)}…`;
  return t;
}

export async function renderDigest(d: Digest, theme: DigestTheme = digestSettings().theme): Promise<Buffer> {
  const P = PALETTES[theme];
  const W = 1200;
  const H = 675;
  const canvas = new Canvas(W, H);
  const ctx: any = canvas.getContext('2d');
  const b = brand();
  const accent = /^#[0-9a-f]{6}$/i.test(b.color) ? b.color : '#5a4bd1';

  // background: deep night with the brand colour glowing from the top left
  const bg = ctx.createLinearGradient(0, 0, W, H);
  bg.addColorStop(0, P.bgA);
  bg.addColorStop(1, P.bgB);
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);
  const glow = ctx.createRadialGradient(160, 40, 10, 160, 40, 700);
  glow.addColorStop(0, `${accent}${P.glow}`);
  glow.addColorStop(1, `${accent}00`);
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, W, H);

  ctx.fillStyle = P.ink;
  ctx.font = `bold 44px ${SANS}`;
  ctx.fillText(`Неделя на ${b.name}`, 56, 92);
  ctx.fillStyle = P.ink2;
  ctx.font = `600 22px ${SANS}`;
  ctx.fillText(`${dateRu(d.from)} – ${dateRu(d.to)}`, 56, 128);

  // four numbers
  type Tone = 'up' | 'down' | 'same';
  const arrow = (pct: number | null, suffix: string): [string, Tone] => {
    const tr = trendText(pct);
    return tr ? [`${tr.text} ${suffix}`.trim(), tr.kind] : ['', 'same'];
  };
  const peakWhen = d.totals.peakAt ? new Date(d.totals.peakAt).toLocaleString('ru-RU', { weekday: 'short', hour: '2-digit', minute: '2-digit', timeZone: tz() }).replace(',', '') : '';
  const stats: [string, string, string, Tone][] = [
    [String(d.totals.players), 'игроков', ...arrow(delta(d.totals.players, d.totals.prevPlayers), 'к прошлой неделе')],
    [String(d.totals.peak), 'пик онлайна', [peakWhen, d.totals.peakServer ?? ''].filter(Boolean).join(' · '), 'same'],
    [d.totals.hours.toLocaleString('ru-RU'), 'часов в игре', ...arrow(delta(d.totals.hours, d.totals.prevHours), 'к прошлой неделе')],
    [d.totals.uptime == null ? '–' : `${String(d.totals.uptime).replace('.', ',')}%`, 'доступность', d.totals.incidents ? `${d.totals.incidents} сбоев` : 'без сбоев', d.totals.incidents ? 'down' : 'up'],
  ];
  stats.forEach(([v, k, hint, tone], i) => {
    const x = 56 + i * 276;
    ctx.fillStyle = P.card;
    ctx.beginPath();
    ctx.roundRect(x, 160, 256, 140, 22);
    ctx.fill();
    ctx.fillStyle = P.ink;
    ctx.font = `bold 52px ${SANS}`;
    ctx.fillText(v, x + 22, 228);
    ctx.fillStyle = P.ink2;
    ctx.font = `bold 20px ${SANS}`;
    ctx.fillText(k, x + 22, 260);
    ctx.fillStyle = tone === 'down' ? P.bad : tone === 'up' ? P.ok : P.ink3;
    ctx.font = `600 15px ${SANS}`;
    let short = hint;
    while (short.length > 3 && ctx.measureText(short).width > 220) short = short.slice(0, -1);
    ctx.fillText(short === hint ? short : `${short}…`, x + 22, 286);
  });

  // players per day
  const max = Math.max(1, ...d.days.map((x) => x.players));
  const bx = 56;
  const by = 340;
  const bw = 520;
  const bh = 270;
  ctx.fillStyle = P.ink2;
  ctx.font = `bold 18px ${SANS}`;
  ctx.fillText('Игроков в день', bx, by);
  const slot = bw / 7;
  const top = busiestDay(d.days.map((x) => x.players));
  d.days.forEach((x, i) => {
    const h = Math.max(4, ((bh - 70) * x.players) / max);
    const gx = bx + i * slot + 10;
    const gy = by + bh - 40 - h;
    const g = ctx.createLinearGradient(0, gy, 0, gy + h);
    g.addColorStop(0, accent);
    g.addColorStop(1, `${accent}66`);
    ctx.fillStyle = g;
    // the busiest day keeps the full colour, the rest are toned down
    ctx.globalAlpha = top < 0 || i === top ? 1 : 0.55;
    ctx.beginPath();
    ctx.roundRect(gx, gy, slot - 20, h, 10);
    ctx.fill();
    ctx.globalAlpha = 1;
    ctx.fillStyle = P.ink;
    ctx.font = `bold 17px ${SANS}`;
    ctx.textAlign = 'center';
    ctx.fillText(String(x.players), gx + (slot - 20) / 2, gy - 8);
    ctx.fillStyle = P.ink3;
    ctx.font = `600 15px ${SANS}`;
    const [, m, day] = x.day.split('-');
    ctx.fillText(`${Number(day)}.${m}`, gx + (slot - 20) / 2, by + bh - 12);
    ctx.textAlign = 'left';
  });

  // servers
  const sx = 640;
  ctx.fillStyle = P.ink2;
  ctx.font = `bold 18px ${SANS}`;
  ctx.fillText('Серверы', sx, by);
  const headW = ctx.measureText('Серверы').width;
  ctx.fillStyle = P.ink4;
  ctx.font = `600 14px ${SANS}`;
  ctx.fillText('линия: пик онлайна по дням · %: к прошлой неделе', sx + headW + 16, by);
  const { shown, hidden } = splitServers(d.servers, 4);
  // servers of one project start with the same words: show the part that tells them apart
  const names = stripCommonPrefix(shown.map((s) => s.name));
  shown.forEach((s, i) => {
    const y = by + 22 + i * 50;
    ctx.fillStyle = P.card;
    ctx.beginPath();
    ctx.roundRect(sx, y, 504, 46, 12);
    ctx.fill();
    ctx.fillStyle = P.ink;
    // up to two lines; a line that is still too wide is cut by pixels
    ctx.font = `bold 16px ${SANS}`;
    const lines = wrapName(names[i] ?? s.name, 17, 2).map((ln) => {
      let l = ln;
      while (l.length > 3 && ctx.measureText(l).width > 176) l = `${l.slice(0, -2)}…`;
      return l;
    });
    lines.forEach((ln, k) => ctx.fillText(ln, sx + 14, lines.length === 1 ? y + 27 : y + 19 + k * 16));
    // the week in one line: the highest online of each day
    const pts = sparkPoints(s.daily, 70, 20);
    const px = sx + 200;
    const py = y + 11;
    ctx.strokeStyle = accent;
    ctx.lineWidth = 2.5;
    ctx.lineJoin = 'round';
    ctx.beginPath();
    pts.forEach(([x, yy], k) => (k ? ctx.lineTo(px + x, py + yy) : ctx.moveTo(px + x, py + yy)));
    ctx.stroke();
    // players, and how that compares with the week before
    ctx.font = `600 16px ${SANS}`;
    ctx.fillStyle = P.ink2;
    ctx.fillText(`${s.players} игр.`, sx + 290, y + 20);
    const tr = trendText(changePct(s.players, s.prevPlayers));
    if (tr) {
      ctx.font = `600 13px ${SANS}`;
      ctx.fillStyle = tr.kind === 'down' ? P.bad : tr.kind === 'up' ? P.ok : P.ink3;
      ctx.fillText(tr.text, sx + 290, y + 36);
    }
    ctx.font = `600 16px ${SANS}`;
    const ok = s.incidents === 0;
    ctx.fillStyle = ok ? P.ok : s.downMinutes >= 60 ? P.bad : P.warn;
    ctx.fillText(s.uptime == null ? '–' : `${String(s.uptime).replace('.', ',')}%`, sx + 410, y + 28);
    // the uptime as a thin bar along the bottom edge of the row
    ctx.fillStyle = P.card;
    ctx.beginPath();
    ctx.roundRect(sx + 14, y + 40, 476, 3, 1.5);
    ctx.fill();
    const bar = uptimeBar(s.uptime, 476);
    if (bar > 0) {
      ctx.fillStyle = ok ? P.ok : s.downMinutes >= 60 ? P.bad : P.warn;
      ctx.beginPath();
      ctx.roundRect(sx + 14, y + 40, bar, 3, 1.5);
      ctx.fill();
    }
  });
  // too many servers for the picture: one row says how many more there are
  if (hidden.length) {
    const y = by + 22 + shown.length * 50;
    ctx.fillStyle = P.card;
    ctx.beginPath();
    ctx.roundRect(sx, y, 504, 46, 12);
    ctx.fill();
    ctx.fillStyle = P.ink2;
    ctx.font = `bold 16px ${SANS}`;
    ctx.fillText(`ещё ${hidden.length} ${hidden.length === 1 ? 'сервер' : hidden.length < 5 ? 'сервера' : 'серверов'}`, sx + 14, y + 28);
    ctx.font = `600 16px ${SANS}`;
    ctx.fillStyle = P.ink3;
    ctx.fillText(`${hidden.reduce((n, x) => n + x.players, 0)} игр.`, sx + 290, y + 28);
  }
  // the hero of the week: the player with the most hours, the two after them in small print
  const rowsEnd = by + 22 + (shown.length + (hidden.length ? 1 : 0)) * 50;
  const hero = d.top[0];
  if (hero) {
    const hy = rowsEnd + 4;
    ctx.fillStyle = P.card;
    ctx.beginPath();
    ctx.roundRect(sx, hy, 504, 52, 14);
    ctx.fill();
    ctx.fillStyle = avatarColor(hero.name);
    ctx.beginPath();
    ctx.arc(sx + 32, hy + 26, 18, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#0e0c1b';
    ctx.font = `800 20px ${SANS}`;
    ctx.textAlign = 'center';
    ctx.fillText(initialOf(hero.name), sx + 32, hy + 33);
    ctx.textAlign = 'left';
    ctx.fillStyle = P.ink4;
    ctx.font = `700 12px ${SANS}`;
    ctx.fillText('ГЕРОЙ НЕДЕЛИ', sx + 62, hy + 20);
    const others = d.top.slice(1, 3).map((p) => `${p.name} ${Math.round(p.hours)} ч`).join(' · ');
    if (others) {
      ctx.font = `600 13px ${SANS}`;
      ctx.fillStyle = P.ink3;
      ctx.textAlign = 'right';
      let o = others;
      while (o.length > 4 && ctx.measureText(o).width > 250) o = `${o.slice(0, -2)}…`;
      ctx.fillText(o, sx + 490, hy + 20);
      ctx.textAlign = 'left';
    }
    ctx.fillStyle = P.ink;
    ctx.font = `bold 19px ${SANS}`;
    ctx.fillText(fitText(ctx, hero.name, 250), sx + 62, hy + 42);
    ctx.fillStyle = accent;
    ctx.font = `bold 20px ${SANS}`;
    ctx.textAlign = 'right';
    ctx.fillText(`${Math.round(hero.hours)} ч`, sx + 490, hy + 42);
    ctx.textAlign = 'left';
  }

  // under everything: what happened this week, in up to three small pills
  let ex = 56;
  const tone = { ok: P.ok, warn: P.warn, bad: P.bad, info: accent } as const;
  for (const e of d.events) {
    ctx.font = `600 15px ${SANS}`;
    const text = fitText(ctx, e.text, 330);
    const w = ctx.measureText(text).width + 40;
    ctx.fillStyle = P.card;
    ctx.beginPath();
    ctx.roundRect(ex, 628, w, 32, 16);
    ctx.fill();
    ctx.fillStyle = tone[e.tone];
    ctx.beginPath();
    ctx.arc(ex + 16, 644, 5, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = P.ink2;
    ctx.fillText(text, ex + 28, 649);
    ex += w + 10;
  }
  return canvas.toBuffer('png');
}

// ---------- the message ----------
const sign = (to: number) => crypto.createHmac('sha256', JWT_SECRET).update(`digest:${to}`).digest('hex').slice(0, 20);

export function digestMessage(d: Digest) {
  const base = publicBase();
  const t = d.totals;
  const lines = [
    `👥 **${t.players}** ${t.players === 1 ? 'игрок' : 'игроков'}${deltaText(delta(t.players, t.prevPlayers))}, из них новых **${t.newPlayers}**`,
    `🔥 Пик онлайна **${t.peak}**${t.peakServer ? ` на ${t.peakServer}` : ''}`,
    `⏱️ **${t.hours.toLocaleString('ru-RU')}** часов в игре${deltaText(delta(t.hours, t.prevHours))}`,
    `🟢 Доступность **${t.uptime == null ? '–' : `${String(t.uptime).replace('.', ',')}%`}**${t.incidents ? `, сбоев: ${t.incidents}` : ', без сбоев'}`,
  ];
  if (d.top.length) lines.push(`🏆 Больше всех играли: ${d.top.slice(0, 3).map((p) => `**${p.name}** (${Math.round(p.hours)} ч)`).join(', ')}`);
  return {
    content: '',
    mention: 'none' as const,
    // below the picture: a button to the full numbers on the site
    ...(base ? { actions: [{ label: '📈 Подробности на сайте', url: `${base}/status` }] } : {}),
    embed: {
      title: `📊 Неделя на ${brand().name}: ${dateRu(d.from)} – ${dateRu(d.to)}`,
      description: lines.join('\n'),
      color: 0x5865f2,
      ...(base ? { url: `${base}/status`, image: { url: `${base}/api/digest/${d.to}-${sign(d.to)}.png` } } : {}),
      footer: { text: 'CoreGSM · итоги недели' },
      timestamp: new Date(d.to).toISOString(),
    },
  };
}

export function sendDigest(now = Date.now()): boolean {
  const s = digestSettings();
  const channel = s.channelId || alertSettings().channelId;
  if (!channel) return false;
  enqueueAlert('digest', 'Итоги недели', digestMessage(buildDigest(now)), channel);
  setSetting('digest_last_sent', String(now));
  return true;
}

/** once every 10 minutes: is it the chosen weekday and hour, and has this week's digest not gone out yet? */
export function digestDue(now = Date.now()): boolean {
  const s = digestSettings();
  if (!s.enabled) return false;
  const p = localParts(now, tz());
  return p.dow === s.weekday && p.hour === s.hour && now - s.lastSent > 2 * DAY;
}

let timer: NodeJS.Timeout | undefined;
export function startDigestTimer(): void {
  timer = setInterval(() => {
    try {
      if (digestDue()) sendDigest();
    } catch (e) {
      log.error('weekly digest failed:', (e as Error).message);
    }
  }, 10 * 60_000);
  timer.unref();
}

export function registerDigest({ app, admin }: { app: Express; admin: RequestHandler }): void {
  const payload = () => ({ ...digestSettings(), preview: buildDigest() });

  app.get('/api/digest', admin, (_req, res) => res.json(payload()));

  app.put('/api/digest', admin, (req, res) => {
    const b = z
      .object({
        enabled: z.boolean().optional(),
        channelId: z.string().regex(/^(\d{15,25})?$/).optional(),
        weekday: z.number().int().min(0).max(6).optional(),
        hour: z.number().int().min(0).max(23).optional(),
        theme: z.enum(['dark', 'light']).optional(),
      })
      .safeParse(req.body);
    if (!b.success) return res.status(400).json({ error: 'Проверьте поля' });
    if (b.data.enabled && !(b.data.channelId ?? (digestSettings().channelId || alertSettings().channelId))) {
      return res.status(400).json({ error: 'Сначала выберите канал для оповещений' });
    }
    if (b.data.enabled !== undefined) setSetting('digest_enabled', b.data.enabled ? '1' : '0');
    if (b.data.channelId !== undefined) setSetting('digest_channel', b.data.channelId);
    if (b.data.weekday !== undefined) setSetting('digest_weekday', String(b.data.weekday));
    if (b.data.hour !== undefined) setSetting('digest_hour', String(b.data.hour));
    if (b.data.theme !== undefined) setSetting('digest_theme', b.data.theme);
    res.json(payload());
  });

  app.post('/api/digest/send', admin, (_req, res) => {
    if (!sendDigest()) return res.status(400).json({ error: 'Сначала выберите канал для оповещений' });
    res.json(payload());
  });

  // the picture of a digest: the administrator's preview, or the signed address in the Discord message
  app.get('/api/digest/preview.png', admin, async (_req, res, next) => {
    try {
      res.set({ 'Content-Type': 'image/png', 'Cache-Control': 'no-store' }).send(await renderDigest(buildDigest()));
    } catch (e) {
      next(e);
    }
  });
  app.get('/api/digest/:to-:sig.png', param('to'), param('sig', /^[0-9a-f]{20}$/), async (req, res, next) => {
    const to = Number(req.params.to);
    if (req.params.sig !== sign(to) || to > Date.now() + 60_000) return res.status(404).json({ error: 'Не найдено' });
    try {
      res.set({ 'Content-Type': 'image/png', 'Cache-Control': 'public, max-age=604800, immutable' }).send(await renderDigest(buildDigest(to)));
    } catch (e) {
      next(e);
    }
  });
}
