  cat > "$APP_DIR/core-backend/src/overview.ts" << '__COREGSM_EOF__'
/**
 * Data for the main page (additive, read-only):
 *   GET /api/overview?hours=24   total players over time, the peak, current totals, active / upcoming maintenance
 *   GET /api/events/recent?limit=8   the latest up / down / peak / maintenance events across all servers
 * Both are public like /api/status (the `viewer` middleware decides who may look).
 */
import type { Express, RequestHandler } from 'express';
import { db } from './db.js';
import { nextOccurrence, occurrenceAt, occurrencesBetween, type WindowRow } from './maintenance.js';

const NAME_SQL = `COALESCE(NULLIF(s.name, ''), NULLIF(st.name, ''), NULLIF(s.display_address, ''), s.host || ':' || s.port)`;
const DAY = 86_400_000;
const POINTS = 96;

export interface OverviewPoint {
  ts: number;
  players: number;
  online: number;
}

/** sums the last sample of every server in every time bucket */
export function overviewPoints(since: number, bucketMs: number): OverviewPoint[] {
  const rows = db
    .prepare(
      `SELECT b, server_id, players, online FROM (
         SELECT ts / CAST(? AS INTEGER) AS b, server_id, players, online,
                ROW_NUMBER() OVER (PARTITION BY server_id, ts / CAST(? AS INTEGER) ORDER BY ts DESC) AS rn
         FROM history WHERE ts > ?
       ) WHERE rn = 1`,
    )
    .all(bucketMs, bucketMs, since) as { b: number; server_id: number; players: number; online: number }[];
  const sums = new Map<number, OverviewPoint>();
  for (const r of rows) {
    const p = sums.get(r.b) ?? { ts: r.b * bucketMs, players: 0, online: 0 };
    if (r.online) {
      p.players += r.players;
      p.online += 1;
    }
    sums.set(r.b, p);
  }
  return [...sums.values()].sort((a, b) => a.ts - b.ts);
}

export function peakOf(points: OverviewPoint[]): { ts: number; players: number } | null {
  let best: OverviewPoint | null = null;
  for (const p of points) if (p.players > 0 && (!best || p.players >= best.players)) best = p;
  return best ? { ts: best.ts, players: best.players } : null;
}

export interface RecentEvent {
  ts: number;
  serverId: number | null;
  serverName: string | null;
  type: 'up' | 'down' | 'peak' | 'maintenance';
  players?: number;
  /** the window title (maintenance events only) */
  name?: string;
}

/** the same sources as `details.events` of a single server, taken for every server and merged */
export function recentEvents(limit: number, now = Date.now()): RecentEvent[] {
  const names = new Map<number, string>();
  for (const r of db.prepare(`SELECT s.id, ${NAME_SQL} AS n FROM servers s LEFT JOIN status st ON st.server_id = s.id`).all() as { id: number; n: string }[]) names.set(r.id, r.n);

  const out: RecentEvent[] = [];
  const week = now - 7 * DAY;
  const flips = db
    .prepare(
      `SELECT server_id, ts, online FROM (
         SELECT server_id, ts, online, LAG(online) OVER (PARTITION BY server_id ORDER BY ts) AS prev FROM history WHERE ts > ?
       ) WHERE prev IS NOT NULL AND prev <> online ORDER BY ts DESC LIMIT 300`,
    )
    .all(week) as { server_id: number; ts: number; online: number }[];
  for (const f of flips) {
    if (names.has(f.server_id)) out.push({ ts: f.ts, serverId: f.server_id, serverName: names.get(f.server_id) ?? null, type: f.online ? 'up' : 'down' });
  }
  // the busiest moment of the last 24 h of every server
  const peaks = db
    .prepare('SELECT server_id, MAX(players) AS players, ts FROM history WHERE ts > ? GROUP BY server_id HAVING MAX(players) > 0')
    .all(now - DAY) as { server_id: number; players: number; ts: number }[];
  for (const p of peaks) {
    if (names.has(p.server_id)) out.push({ ts: p.ts, serverId: p.server_id, serverName: names.get(p.server_id) ?? null, type: 'peak', players: p.players });
  }
  for (const w of db.prepare('SELECT * FROM maintenance_windows').all() as WindowRow[]) {
    if (w.server_id != null && !names.has(w.server_id)) continue;
    for (const o of occurrencesBetween(w, week, now)) {
      out.push({ ts: o.start, serverId: w.server_id, serverName: w.server_id == null ? null : names.get(w.server_id) ?? null, type: 'maintenance', name: w.name });
    }
  }
  out.sort((a, b) => b.ts - a.ts);
  return out.slice(0, limit);
}

export interface OverviewMaintenance {
  id: number;
  serverId: number | null;
  serverName: string | null;
  name: string;
  startTs: number;
  endTs: number;
  active: boolean;
}

/** windows running now plus those starting within a week; running first, then by start */
export function maintenanceOutlook(now = Date.now()): OverviewMaintenance[] {
  const names = new Map<number, string>();
  for (const r of db.prepare(`SELECT s.id, ${NAME_SQL} AS n FROM servers s LEFT JOIN status st ON st.server_id = s.id`).all() as { id: number; n: string }[]) names.set(r.id, r.n);
  const out: OverviewMaintenance[] = [];
  for (const w of db.prepare('SELECT * FROM maintenance_windows ORDER BY id').all() as WindowRow[]) {
    if (w.server_id != null && !names.has(w.server_id)) continue;
    const cur = occurrenceAt(w, now);
    const occ = cur ?? nextOccurrence(w, now);
    if (!occ || (!cur && occ.start - now > 7 * DAY)) continue;
    out.push({ id: w.id, serverId: w.server_id, serverName: w.server_id == null ? null : names.get(w.server_id) ?? null, name: w.name, startTs: occ.start, endTs: occ.end, active: !!cur });
  }
  return out.sort((a, b) => Number(b.active) - Number(a.active) || a.startTs - b.startTs).slice(0, 10);
}

export function registerOverview({ app, viewer }: { app: Express; viewer: RequestHandler }): void {
  app.get('/api/overview', viewer, (req, res) => {
    const hoursRaw = Number(req.query.hours ?? 24);
    const hours = Math.min(168, Math.max(1, Number.isFinite(hoursRaw) ? hoursRaw : 24));
    const now = Date.now();
    const bucketMs = Math.max(60_000, Math.ceil((hours * 3_600_000) / POINTS));
    const points = overviewPoints(now - hours * 3_600_000, bucketMs);
    const cur = db.prepare('SELECT COUNT(*) AS servers FROM servers').get() as { servers: number };
    const live = db
      .prepare('SELECT COUNT(*) AS online, COALESCE(SUM(players), 0) AS players FROM status WHERE online = 1 AND server_id IN (SELECT id FROM servers)')
      .get() as { online: number; players: number };
    res.json({
      hours,
      bucketMs,
      points,
      peak: peakOf(points),
      totals: { players: live.players, servers: cur.servers, online: live.online },
      maintenance: maintenanceOutlook(now),
    });
  });

  app.get('/api/events/recent', viewer, (req, res) => {
    const n = Number(req.query.limit ?? 8);
    const limit = Math.min(50, Math.max(1, Number.isFinite(n) ? Math.floor(n) : 8));
    res.json(recentEvents(limit));
  });
}
__COREGSM_EOF__
  mkdir -p "$APP_DIR/core-backend/src"
  cat > "$APP_DIR/core-backend/src/playerFollows.ts" << '__COREGSM_EOF__'
/**
 * Following a player: a signed-in user asks to be told when a game nick joins any server.
 * The notification goes to the in-panel inbox, to Discord (a DM, when the account is linked and the bot is online)
 * and to the devices with Web Push, like the server subscriptions. One notification per (user, nick) per 30 minutes,
 * so a player who reconnects over and over is not announced over and over.
 *
 *   GET    /api/me/follows            the nicks I follow
 *   PUT    /api/players/:nick/follow  follow (at most 30 nicks)
 *   DELETE /api/players/:nick/follow  stop following
 *
 * gsm.ts calls notifyFollowers() with the sessions a poll has just opened.
 */
import type { Express, Request, RequestHandler } from 'express';
import { db, EFFECTIVE_NAME } from './db.js';
import { enqueueDelivery } from './deliveries.js';
import { dmAvailable, pushToUser } from './subscriptions.js';
import { log } from './logger.js';

export const MAX_FOLLOWS = 30;
/** minimum gap between two notifications about the same nick for the same user */
export const FOLLOW_GAP_MS = 30 * 60_000;

db.exec(`
CREATE TABLE IF NOT EXISTS player_follows (
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  nick_key TEXT NOT NULL,
  nick TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  last_notified_at INTEGER,
  PRIMARY KEY (user_id, nick_key)
);
CREATE INDEX IF NOT EXISTS idx_follows_nick ON player_follows(nick_key);
`);

/** the key a nick is compared by: case does not matter */
export const nickKey = (nick: string): string => nick.trim().toLowerCase();

/** a usable nick: 1..64 characters after trimming */
export const validNick = (nick: unknown): nick is string => typeof nick === 'string' && nick.trim().length >= 1 && nick.trim().length <= 64;

export const mayNotifyFollow = (last: number | null, now: number): boolean => last === null || now - last >= FOLLOW_GAP_MS;

export const followText = (nick: string, serverName: string, address: string): string =>
  `🎮 ${nick} зашёл на «${serverName}».${address ? ` Адрес: ${address}` : ''}`;

/** Poller hook: sessions that were just opened. Never throws into the poller. */
export function notifyFollowers(serverId: number, names: string[], now = Date.now()): number {
  try {
    if (!names.length) return 0;
    const keys = [...new Set(names.map(nickKey))];
    const found = db
      .prepare(
        `SELECT f.user_id, f.nick_key, f.last_notified_at, u.discord_id FROM player_follows f
           JOIN users u ON u.id = f.user_id AND u.status = 'active'
         WHERE f.nick_key IN (${keys.map(() => '?').join(',')})`,
      )
      .all(...keys) as { user_id: number; nick_key: string; last_notified_at: number | null; discord_id: string | null }[];
    if (!found.length) return 0;
    const info = db
      .prepare(`SELECT ${EFFECTIVE_NAME} AS n, s.display_address, s.host, s.port FROM servers s LEFT JOIN status st ON st.server_id = s.id WHERE s.id = ?`)
      .get(serverId) as { n: string; display_address: string; host: string; port: number } | undefined;
    if (!info) return 0;
    const address = info.display_address || `${info.host}:${info.port}`;
    const shown = new Map(names.map((n) => [nickKey(n), n]));
    const insert = db.prepare('INSERT INTO user_notifications (user_id, ts, kind, server_id, text) VALUES (?, ?, ?, ?, ?)');
    const touch = db.prepare('UPDATE player_follows SET last_notified_at = ? WHERE user_id = ? AND nick_key = ?');
    let n = 0;
    for (const f of found) {
      if (!mayNotifyFollow(f.last_notified_at, now)) continue;
      const text = followText(shown.get(f.nick_key) ?? f.nick_key, info.n, address);
      insert.run(f.user_id, now, 'player_online', serverId, text);
      touch.run(now, f.user_id, f.nick_key);
      if (f.discord_id && dmAvailable()) enqueueDelivery({ kind: 'dm', refId: null, target: f.discord_id, payload: { content: text, summary: text.slice(0, 120) } });
      pushToUser(f.user_id, { title: info.n, body: text, url: `/servers/${serverId}`, tag: `follow-${f.nick_key}` });
      n++;
    }
    return n;
  } catch (e) {
    log.error('player follows failed', (e as Error).message);
    return 0;
  }
}

export function registerPlayerFollows(deps: { app: Express; auth: RequestHandler; userId: (req: Request) => number }): void {
  const { app, auth, userId } = deps;

  app.get('/api/me/follows', auth, (req, res) => {
    const rows = db.prepare('SELECT nick, created_at FROM player_follows WHERE user_id = ? ORDER BY created_at DESC').all(userId(req)) as { nick: string; created_at: number }[];
    res.json(rows.map((r) => ({ nick: r.nick, createdAt: r.created_at })));
  });

  app.put('/api/players/:nick/follow', auth, (req, res) => {
    const nick = String(req.params.nick ?? '');
    if (!validNick(nick)) return res.status(400).json({ error: 'Укажите ник игрока' });
    const uid = userId(req);
    const key = nickKey(nick);
    const have = db.prepare('SELECT 1 FROM player_follows WHERE user_id = ? AND nick_key = ?').get(uid, key);
    if (!have) {
      const n = (db.prepare('SELECT COUNT(*) AS n FROM player_follows WHERE user_id = ?').get(uid) as { n: number }).n;
      if (n >= MAX_FOLLOWS) return res.status(400).json({ error: `Можно следить не больше чем за ${MAX_FOLLOWS} игроками` });
      db.prepare('INSERT INTO player_follows (user_id, nick_key, nick, created_at) VALUES (?, ?, ?, ?)').run(uid, key, nick.trim(), Date.now());
    }
    res.json({ nick: nick.trim(), following: true });
  });

  app.delete('/api/players/:nick/follow', auth, (req, res) => {
    const nick = String(req.params.nick ?? '');
    if (!validNick(nick)) return res.status(400).json({ error: 'Укажите ник игрока' });
    db.prepare('DELETE FROM player_follows WHERE user_id = ? AND nick_key = ?').run(userId(req), nickKey(nick));
    res.json({ nick: nick.trim(), following: false });
  });
}
