  res.json(rows.map((s) => ({ id: s.id, createdAt: s.created_at, lastSeen: s.last_seen, ip: s.ip, ua: s.ua, current: s.id === cur })));
});
router.post('/api/sessions/revoke-others', auth, (req: AuthedRequest, res) => {
