/** an error answer from the API; `data` is the whole JSON body (retryAfter, attemptsLeft, pending ...) */
export class ApiError extends Error {
  status: number;
  data: Record<string, unknown>;
  constructor(message: string, status = 0, data: Record<string, unknown> = {}) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.data = data;
  }
}

/** how many requests of the panel are in flight (the progress strip under the header listens) */
let inflight = 0;
const busyListeners = new Set<(n: number) => void>();
export const onBusy = (fn: (n: number) => void): (() => void) => { busyListeners.add(fn); return () => { busyListeners.delete(fn); }; };
const busy = (d: number) => { inflight = Math.max(0, inflight + d); busyListeners.forEach((f) => f(inflight)); };

export async function api<T>(path: string, method = 'GET', body?: unknown): Promise<T> {
  busy(1);
  try {
    return await request<T>(path, method, body);
  } finally {
    busy(-1);
  }
}

async function request<T>(path: string, method: string, body?: unknown): Promise<T> {
  const res = await fetch('/api' + path, {
    method,
    headers: {
      'Content-Type': 'application/json',
      // only a real in-memory token (legacy migration); the cookie session needs no header
      ...(memToken ? { Authorization: `Bearer ${memToken}` } : {}),
    },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const data = await res.json().catch(() => ({}));
  if (res.status === 401 && path !== '/auth/login') {
    setToken('');
    window.dispatchEvent(new Event('coregsm:logout'));
  }
  if (!res.ok) throw new ApiError(localizeError(data) ?? `Ошибка ${res.status}`, res.status, data as Record<string, unknown>);
  return data as T;
}

