    <div className="srv-hero srv-hero-skel tile flex min-h-[280px] flex-col gap-3 p-5 lg:p-6">
      <div className="flex items-start gap-3">
        <div className="skeleton h-12 w-12 shrink-0 rounded-2xl" />
