// The «Серверы» table of the admin area: search, filters, a checkbox per row for bulk actions, the figures of every
// server (status, players, ping, uptime, a 24 h curve) and the row actions as icons. On a phone it is a list of cards.
import { Fragment, useEffect, useMemo, useState } from 'react';
import type { Server } from '../api';
import { confirmDialog } from '../confirm';
import { t, useI18n, type TKey } from '../i18n';
import { gameColor, gameLabel } from '../games';
import RowMenu, { type RowMenuItem } from '../components/RowMenu';
import { AnimatedNumber, GameAvatar, IconEdit, IconRefresh, MiniSpark, StatusPill, ago, isLag, toast } from '../ui';
import { countServers, filterServers, loadColumns, loadTableState, saveColumns, saveTableState, TABLE_COLUMNS, type ServerFilter, type TableColumn } from './adminServersLogic';

export interface TableActions {
  isAdmin: boolean;
  busyId: number | null;
  uptime: Map<number, number>;
  /** Discord channels bound to each server */
  bindings: Map<number, number>;
  onMaintenance: (s: Server) => void;
  onRefresh: (s: Server) => void;
  onEdit: (s: Server) => void;
  onRemove: (s: Server) => void;
  /** refresh / delete several at once; resolve when done */
  onRefreshMany: (list: Server[]) => Promise<void>;
  onRemoveMany: (list: Server[]) => Promise<void>;
  /** move a server one step up/down in the manual order (the ids on screen, in order) */
  onMove: (s: Server, dir: -1 | 1, shown: number[]) => void;
}

const FILTERS: [ServerFilter, TKey][] = [['all', 'adm.tbl.all'], ['online', 'adm.tbl.online'], ['problems', 'adm.tbl.problems']];
/** «2 ч», «15 мин»: how long a state has lasted */
export function spanText(ms: number): string {
  const m = Math.floor(ms / 60_000);
  if (m < 1) return 'меньше минуты';
  if (m < 60) return `${m} мин`;
  const h = Math.floor(m / 60);
  if (h < 48) return `${h} ч`;
  return `${Math.floor(h / 24)} дн`;
}
const stateLine = (s: Server): string | null => {
  if (s.maintenance || !s.hasStatus || !s.stateSince) return null;
  return `${s.online ? 'работает' : 'не отвечает'} · ${spanText(Date.now() - s.stateSince)}`;
};
const pct = (v: number | undefined) => (v == null ? '–' : `${(Math.round(v * 10) / 10).toLocaleString('ru-RU')}%`);

export function AdminServersTable({ servers, a }: { servers: Server[]; a: TableActions }) {
  useI18n();
  const [saved] = useState(loadTableState);
  const [filter, setFilter] = useState<ServerFilter>(saved.filter);
  const [query, setQuery] = useState(saved.query);
  useEffect(() => { saveTableState(filter, query); }, [filter, query]);
  const [cols, setCols] = useState<TableColumn[]>(loadColumns);
  const toggleCol = (c: TableColumn) => setCols((l) => { const n = l.includes(c) ? l.filter((x) => x !== c) : TABLE_COLUMNS.filter((x) => x === c || l.includes(x)); saveColumns(n); return n; });
  const has = (c: TableColumn) => cols.includes(c);
  const [sel, setSel] = useState<number[]>([]);
  const [busy, setBusy] = useState(false);
  const [open, setOpen] = useState<number[]>([]);
  const [view, setView] = useState<'table' | 'cards'>(() => { try { return localStorage.getItem('coregsm_admin_srv_view') === 'cards' ? 'cards' : 'table'; } catch { return 'table'; } });
  const pickView = (v: 'table' | 'cards') => { setView(v); try { localStorage.setItem('coregsm_admin_srv_view', v); } catch { /* not remembered */ } };
  const counts = useMemo(() => countServers(servers), [servers]);
  const rows = useMemo(() => filterServers(servers, filter, query), [servers, filter, query]);
  const shownIds = rows.map((s) => s.id);
  const canMove = filter === 'all' && !query.trim() && rows.length > 1;
  const picked = servers.filter((s) => sel.includes(s.id));
  const allOn = rows.length > 0 && shownIds.every((id) => sel.includes(id));
  const toggle = (id: number) => setSel((l) => (l.includes(id) ? l.filter((x) => x !== id) : [...l, id]));
  const toggleAll = () => setSel((l) => (allOn ? l.filter((id) => !shownIds.includes(id)) : [...new Set([...l, ...shownIds])]));

  const flip = (id: number) => setOpen((l) => (l.includes(id) ? l.filter((x) => x !== id) : [...l, id]));
  const copy = async (s: Server) => {
    try { await navigator.clipboard.writeText(`${s.host}:${s.port}`); toast(t('adm.tbl.copied')); } catch { toast(t('nw.copyFail'), 'err'); }
  };

  /** the rest of a row's actions: a text menu behind «⋯» */
  const menuItems = (s: Server): RowMenuItem[] => [
    ...(canMove ? [
      { key: 'up', label: t('adm.tbl.up'), disabled: s.id === shownIds[0], onSelect: () => a.onMove(s, -1, shownIds) },
      { key: 'down', label: t('adm.tbl.down'), disabled: s.id === shownIds[shownIds.length - 1], onSelect: () => a.onMove(s, 1, shownIds) },
    ] : []),
    { key: 'bind', label: t('adm.tbl.bind'), href: `/admin/discord/new/${s.id}`, sep: canMove },
    { key: 'maint', label: s.maintenance ? t('adm.tbl.maintOff') : t('adm.tbl.maintOn'), onSelect: () => a.onMaintenance(s) },
    ...(a.isAdmin ? [{ key: 'del', label: t('adm.srv.delete'), danger: true, sep: true, onSelect: () => a.onRemove(s) }] : []),
  ];

  const many = async (fn: (list: Server[]) => Promise<void>) => {
    setBusy(true);
    try { await fn(picked); setSel([]); } finally { setBusy(false); }
  };
  const removeMany = async () => {
    if (!(await confirmDialog({ title: t('adm.tbl.deleteQ', { n: picked.length }), text: t('adm.tbl.deleteText'), confirmLabel: t('adm.srv.delete'), danger: true }))) return;
    await many(a.onRemoveMany);
  };

  return (
    <div className="adm-st space-y-3">
      <div className="flex flex-wrap items-center gap-2.5">
        <nav className="seg flex w-fit max-w-full overflow-x-auto" aria-label={t('adm.tbl.filter')}>
          {FILTERS.map(([id, label]) => (
            <button key={id} type="button" className="seg-item whitespace-nowrap" aria-pressed={filter === id} onClick={() => setFilter(id)}>
              {t(label)} · {counts[id]}
            </button>
          ))}
        </nav>
        <div className="seg hidden w-fit md:flex" role="group" aria-label="Вид списка">
          <button type="button" className="seg-item" aria-pressed={view === 'table'} onClick={() => pickView('table')}>Таблица</button>
          <button type="button" className="seg-item" aria-pressed={view === 'cards'} onClick={() => pickView('cards')}>Карточки</button>
        </div>
        <details className="adm-cols hidden md:block">
          <summary className="seg-item cursor-pointer select-none">{t('adm.cols')}</summary>
          <div className="adm-cols-pop" role="group" aria-label={t('adm.cols')}>
            {TABLE_COLUMNS.map((c) => (
              <label key={c} className="flex cursor-pointer items-center gap-2 px-2 py-1 font-semibold">
                <input type="checkbox" className="srv-check" checked={has(c)} onChange={() => toggleCol(c)} />{t(`adm.col.${c}` as TKey)}
              </label>
            ))}
          </div>
        </details>
        <label className="adm-search ml-auto">
          <span aria-hidden>⌕</span>
          <input type="search" value={query} onChange={(e) => setQuery(e.target.value)} placeholder={t('adm.tbl.search')} aria-label={t('adm.tbl.search')} />
        </label>
      </div>

      {picked.length > 0 && (
        <div className="adm-bulk adm-bulk-float" role="region" aria-label={t('adm.tbl.selected')}>
          <b>{t('adm.tbl.picked', { n: picked.length })}</b>
          <button type="button" className="btn btn-soft btn-sm" disabled={busy} onClick={() => void many(a.onRefreshMany)}>{t('adm.tbl.poll')}</button>
          {a.isAdmin && <button type="button" className="btn btn-danger btn-sm" disabled={busy} onClick={() => void removeMany()}>{t('adm.srv.delete')}</button>}
          <button type="button" className="btn btn-ghost btn-sm ml-auto" onClick={() => setSel([])}>{t('adm.tbl.clear')}</button>
        </div>
      )}

      {rows.length === 0 ? (
        <div className="tile px-5 py-8 text-center font-semibold text-mute">
          {t('adm.tbl.none')} <button type="button" className="font-extrabold text-link underline" onClick={() => { setFilter('all'); setQuery(''); }}>{t('adm.tbl.reset')}</button>
        </div>
      ) : (
        <>
          {/* wide screens: a table */}
          <div className={`tile adm-tablewrap hidden p-1.5 ${view === 'table' ? 'md:block' : ''}`}>
            <table className="adm-table">
              <thead>
                <tr>
                  <th className="w-9"><input type="checkbox" className="srv-check" checked={allOn} onChange={toggleAll} aria-label={t('adm.tbl.selectAll')} /></th>
                  <th>{t('adm.tbl.server')}</th>
                  <th>{t('adm.tbl.status')}</th>
                  <th>{t('adm.tbl.players')}</th>
                  <th>{t('adm.tbl.ping')}</th>
                  {has('map') && <th>{t('adm.col.map')}</th>}
                  {has('version') && <th>{t('adm.col.version')}</th>}
                  {has('channels') && <th>{t('adm.col.channels')}</th>}
                  {has('uptime') && <th>{t('adm.tbl.uptime')}</th>}
                  {has('h24') && <th>{t('adm.tbl.h24')}</th>}
                  {has('updated') && <th>{t('adm.col.updated')}</th>}
                  <th aria-label={t('adm.tbl.actions')} />
                </tr>
              </thead>
              <tbody>
                {rows.map((s) => (
                  <Fragment key={s.id}>
                  <tr data-state={s.maintenance ? 'maint' : !s.online && s.hasStatus ? 'off' : isLag(s) ? 'lag' : 'on'} data-selected={sel.includes(s.id) ? 'true' : undefined} className="cursor-pointer" onClick={(e) => { if (!(e.target as HTMLElement).closest('a, button, input, label')) a.onEdit(s); }}>
                    <td><input type="checkbox" className="srv-check" checked={sel.includes(s.id)} onChange={() => toggle(s.id)} aria-label={`${t('adm.tbl.select')}: ${s.name}`} /></td>
                    <td>
                      <div className="flex min-w-0 items-center gap-3">
                        <button type="button" className="adm-expand" aria-expanded={open.includes(s.id)} aria-label={`${t('adm.tbl.details')}: ${s.name}`} title={t('adm.tbl.details')} onClick={() => flip(s.id)}><span aria-hidden>{open.includes(s.id) ? '▾' : '▸'}</span></button>
                        <GameAvatar game={s.game} size={38} />
                        <div className="min-w-0">
                          <a href={`/servers/${s.id}`} className="block max-w-50 xl:max-w-60 truncate font-extrabold leading-tight hover:text-link" title={s.name}>{s.name}</a>
                          <div className="max-w-50 xl:max-w-60 truncate text-xs font-semibold text-mute" title={s.displayAddress ? t('adm.tbl.shownAs', { a: s.displayAddress }) : undefined}>
                            {gameLabel(s.game)} · <button type="button" className="adm-copy font-mono" title={t('adm.tbl.copy')} onClick={() => void copy(s)}>{s.host}:{s.port}</button>
                          </div>
                        </div>
                      </div>
                    </td>
                    <td>
                      <StatusPill online={s.online} known={s.hasStatus} lag={isLag(s)} maintenance={!!s.maintenance} />
                      {stateLine(s) && <div className="mt-0.5 text-xs font-semibold text-mute">{stateLine(s)}</div>}
                    </td>
                    <td className="tabular-nums text-mute">{s.online ? <><b className="text-ink"><AnimatedNumber value={s.players} /></b>/{s.maxPlayers}</> : '—'}</td>
                    <td className="tabular-nums text-mute">{s.online && s.ping != null ? t('adm.tbl.ms', { n: s.ping }) : '—'}</td>
                    {has('map') && <td className="max-w-40 truncate text-mute" title={s.map ?? undefined}>{s.online && s.map ? s.map : '—'}</td>}
                    {has('version') && <td className="max-w-32 truncate font-mono text-xs text-mute" title={s.version ?? undefined}>{s.version || '—'}</td>}
                    {has('channels') && <td className="tabular-nums"><a href="/admin/discord" className="text-link hover:underline">{a.bindings.get(s.id) ?? 0}</a></td>}
                    {has('uptime') && <td className="tabular-nums">{pct(a.uptime.get(s.id))}</td>}
                    {has('h24') && <td><MiniSpark serverId={s.id} color={gameColor(s.game)} /></td>}
                    {has('updated') && <td className="text-mute">{ago(s.updatedAt)}</td>}
                    <td>
                      <div className="flex items-center justify-end gap-1" role="group" aria-label={`${t('adm.tbl.actions')}: ${s.name}`}>
                        <button type="button" className="btn btn-soft btn-sm" aria-label={`${t('adm.tbl.edit')}: ${s.name}`} onClick={() => a.onEdit(s)}><IconEdit /><span>{t('adm.tbl.edit')}</span></button>
                        <button type="button" className="row-act" title={t('adm.tbl.poll')} aria-label={`${t('adm.tbl.poll')}: ${s.name}`} onClick={() => a.onRefresh(s)} disabled={a.busyId === s.id} aria-busy={a.busyId === s.id || undefined}>
                          <IconRefresh spinning={a.busyId === s.id} />
                        </button>
                        <RowMenu label={`${t('adm.tbl.more')}: ${s.name}`} items={menuItems(s)} />
                      </div>
                    </td>
                  </tr>
                  {open.includes(s.id) && (
                    <tr className="adm-detail">
                      <td colSpan={14}>
                        <dl className="adm-detail-grid">
                          <div><dt>{t('adm.tbl.d.addr')}</dt><dd className="font-mono">{s.host}:{s.port}</dd></div>
                          <div><dt>{t('adm.tbl.d.query')}</dt><dd className="font-mono">{s.queryPort ?? '—'}</dd></div>
                          <div><dt>{t('adm.tbl.d.shown')}</dt><dd>{s.displayAddress || '—'}</dd></div>
                          <div><dt>{t('adm.tbl.d.game')}</dt><dd>{gameLabel(s.game)}</dd></div>
                          <div><dt>{t('adm.tbl.d.channels')}</dt><dd><a href="/admin/discord" className="text-link hover:underline">{a.bindings.get(s.id) ?? 0}</a></dd></div>
                          <div><dt>{t('adm.tbl.d.updated')}</dt><dd>{ago(s.updatedAt)}</dd></div>
                          {s.maintenance && <div><dt>{t('adm.tbl.d.maint')}</dt><dd>{s.maintenance.name}</dd></div>}
                        </dl>
                      </td>
                    </tr>
                  )}
                  </Fragment>
                ))}
              </tbody>
            </table>
          </div>

          {/* a phone: a card per server */}
          <div className="adm-cards" data-hide-md={view === 'table' ? 'true' : undefined}>
            {rows.map((s) => (
              <div key={s.id} className="tile adm-card flex flex-wrap items-center gap-x-3 gap-y-2 p-3.5" data-state={s.maintenance ? 'maint' : !s.online && s.hasStatus ? 'off' : isLag(s) ? 'lag' : 'on'} data-selected={sel.includes(s.id) ? 'true' : undefined}>
                <input type="checkbox" className="srv-check" checked={sel.includes(s.id)} onChange={() => toggle(s.id)} aria-label={`${t('adm.tbl.select')}: ${s.name}`} />
                <GameAvatar game={s.game} size={40} />
                <div className="min-w-0 flex-1 basis-40">
                  <a href={`/servers/${s.id}`} className="block wrap-break-word font-extrabold leading-tight">{s.name}</a>
                  <div className="truncate text-xs font-semibold text-mute">{gameLabel(s.game)} · <span className="font-mono">{s.host}:{s.port}</span></div>
                </div>
                <StatusPill online={s.online} known={s.hasStatus} lag={isLag(s)} maintenance={!!s.maintenance} />
                {stateLine(s) && <div className="w-full text-xs font-semibold text-mute">{stateLine(s)}</div>}
                <div className="flex w-full items-center gap-2 text-sm font-semibold text-mute">
                  <span className="tabular-nums">{s.online ? <><b className="text-ink">{s.players}</b>/{s.maxPlayers}</> : '—'}</span>
                  <span>· {ago(s.updatedAt)}</span>
                  <div className="ml-auto flex items-center gap-1">
                    <button type="button" className="row-act" aria-label={`${t('adm.tbl.poll')}: ${s.name}`} onClick={() => a.onRefresh(s)} disabled={a.busyId === s.id}><IconRefresh spinning={a.busyId === s.id} /></button>
                    <button type="button" className="btn btn-soft btn-sm" aria-label={`${t('adm.tbl.edit')}: ${s.name}`} onClick={() => a.onEdit(s)}><IconEdit /><span>{t('adm.tbl.edit')}</span></button>
                    <RowMenu label={`${t('adm.tbl.more')}: ${s.name}`} items={menuItems(s)} />
                  </div>
                </div>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}
__COREGSM_EOF__
  mkdir -p "$APP_DIR/core-frontend/src/pages"
  cat > "$APP_DIR/core-frontend/src/pages/AdminStart.tsx" << '__COREGSM_EOF__'
import { useEffect, useMemo, useState, type ReactNode } from 'react';
import { api, type BotStatus, type SettingsInfo } from '../api';
import { useAuth } from '../auth';
import { t, useI18n } from '../i18n';
import { AdminPage, Burst, PageHead, IconStart, IconServers, IconNews, IconDownload, IconSystem, navigate, toast, usePoll, fail } from '../ui';
import { ADMIN_GROUPS, START_SECTION } from './adminNav';
import { downloadFile } from './Backups';

type StepId = 'server' | 'bot' | 'channel' | 'news' | 'brand';
type StepState = 'done' | 'todo' | 'unknown';

interface StepView {
  id: StepId;
  short: string;
  title: string;
  why: string;
  href: string;
  cta: string;
  state: StepState;
  note?: string;
}

const skipKey = (u: string) => `coregsm_start_skipped_${u}`;
const readSkipped = (u: string): StepId[] => {
  try {
    const v = JSON.parse(localStorage.getItem(skipKey(u)) ?? '[]') as unknown;
    return Array.isArray(v) ? (v.filter((x) => typeof x === 'string') as StepId[]) : [];
  } catch {
    return [];
  }
};
const writeSkipped = (u: string, list: StepId[]) => {
  try { localStorage.setItem(skipKey(u), JSON.stringify(list)); } catch { /* not remembered */ }
};

interface Raw {
  servers: number | null;
  settings: SettingsInfo | null;
  bot: BotStatus | null;
  bindings: number | null;
  news: number | null;
}

const len = (v: unknown) => (Array.isArray(v) ? v.length : null);

/** Reads the real state of the panel and turns it into the checklist. A failing request only marks its step «неизвестно». */
function useStartSteps() {
  const { me, access } = useAuth();
  const { lang } = useI18n();
  const username = me?.username ?? '';
  const [raw, setRaw] = useState<Raw | null>(null);
  const [skipped, setSkipped] = useState<StepId[]>(() => readSkipped(username));

  usePoll(async () => {
    const [s, st, b, bi, n] = await Promise.allSettled([
      api<unknown[]>('/servers'),
      api<SettingsInfo>('/settings'),
      api<BotStatus>('/bot/status'),
      api<unknown[]>('/bindings'),
      api<unknown[]>('/news'),
    ]);
    setRaw({
      servers: s.status === 'fulfilled' ? len(s.value) : null,
      settings: st.status === 'fulfilled' ? st.value : null,
      bot: b.status === 'fulfilled' ? b.value : null,
      bindings: bi.status === 'fulfilled' ? len(bi.value) : null,
      news: n.status === 'fulfilled' ? len(n.value) : null,
    });
  }, 15_000);

  const brand = access.brand;
  const brandDone = brand.name.trim().toLowerCase() !== 'coregsm' || brand.color.toLowerCase() !== '#4f46e5' || brand.hasLogo || !!brand.color2 || !!brand.preset;

  const steps = useMemo<StepView[] | null>(() => {
    if (!raw) return null;
    const st = (n: number | null): StepState => (n === null ? 'unknown' : n > 0 ? 'done' : 'todo');
    let bot: StepState = 'unknown';
    let botNote: string | undefined;
    if (raw.settings) {
      if (!raw.settings.discordTokenSet) bot = 'todo';
      else if (!raw.bot) bot = 'done';
      else if (raw.bot.state === 'online') bot = 'done';
      else {
        bot = 'todo';
        botNote = raw.bot.state === 'error' && raw.bot.error ? t('start.botErr', { e: raw.bot.error }) : t('start.botWait');
      }
    }
    return [
      { id: 'server', short: t('start.server.short'), title: t('start.server.title'), why: t('start.server.why'), href: '/admin/servers/new', cta: t('start.server.cta'), state: st(raw.servers) },
      { id: 'bot', short: t('start.bot.short'), title: t('start.bot.title'), why: t('start.bot.why'), href: '/admin/settings/bot', cta: t('start.bot.cta'), state: bot, note: botNote },
      { id: 'channel', short: t('start.channel.short'), title: t('start.channel.title'), why: t('start.channel.why'), href: '/admin/discord', cta: t('start.channel.cta'), state: st(raw.bindings) },
      { id: 'news', short: t('start.news.short'), title: t('start.news.title'), why: t('start.news.why'), href: '/admin/news/new', cta: t('start.news.cta'), state: st(raw.news) },
      { id: 'brand', short: t('start.brand.short'), title: t('start.brand.title'), why: t('start.brand.why'), href: '/admin/settings/brand', cta: t('start.brand.cta'), state: brandDone ? 'done' : 'todo' },
    ];
  }, [raw, brandDone, lang]);

  const skip = (id: StepId) => setSkipped((cur) => { const n = cur.includes(id) ? cur : [...cur, id]; writeSkipped(username, n); return n; });
  const unskip = (id: StepId) => setSkipped((cur) => { const n = cur.filter((x) => x !== id); writeSkipped(username, n); return n; });

  const doneCount = steps ? steps.filter((s) => s.state === 'done').length : 0;
  // «resolved»: finished or consciously skipped: the start page then stops being the default
  const resolved = steps ? steps.every((s) => s.state === 'done' || skipped.includes(s.id)) : false;
  return { loading: steps === null, steps: steps ?? [], skipped, skip, unskip, doneCount, total: 5, resolved };
}

/** A compact progress card for the sidebar: «Настройка 4 из 5» with the first step left; hidden when everything is done or skipped. */
export function SetupProgress() {
  useI18n();
  const s = useStartSteps();
  if (s.loading || s.resolved || s.steps.length === 0) return null;
  const left = s.steps.find((x) => x.state !== 'done' && !s.skipped.includes(x.id));
  const pct = Math.round((s.doneCount / s.total) * 100);
  return (
    <div className="hidden md:block">
      <a href="/admin/start" className="adm-progress" aria-label={t('start.progress', { a: s.doneCount, b: s.total })}>
        <span className="flex items-baseline justify-between gap-2"><b>{t('start.setup')}</b><span>{t('start.ofTotal', { a: s.doneCount, b: s.total })}</span></span>
        <span className="adm-progress-bar" aria-hidden><i style={{ width: `${pct}%` }} /></span>
        {left && <span className="adm-progress-left">{t('start.next')} {left.short}</span>}
      </a>
    </div>
  );
}

/** `/admin` without a section: «Начало работы» while something is left, «Серверы» when everything is done. */
export function AdminHome() {
  const s = useStartSteps();
  useEffect(() => {
    if (s.loading) return;
    const target = s.resolved ? '/admin/overview' : '/admin/start';
    navigate(target, { replace: true });
  }, [s.loading, s.resolved]);
  return <StartSkeleton />;
}

function StartSkeleton() {
  return (
    <div className="space-y-5" aria-busy="true" aria-label={t('adm.loading')}>
      <div className="skeleton h-14 w-72 rounded-2xl" />
      <div className="skeleton tile h-28" />
      {[0, 1, 2].map((i) => <div key={i} className="skeleton tile h-24" />)}
    </div>
  );
}

const Check = ({ size = 22 }: { size?: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
    <path d="M5 12.5l4.5 4.5L19 7.5" />
  </svg>
);

function Ring({ done, total }: { done: number; total: number }) {
  const r = 30;
  const c = 2 * Math.PI * r;
  return (
    <div className="relative grid h-[76px] w-[76px] shrink-0 place-items-center" aria-hidden>
      <svg width="76" height="76" viewBox="0 0 76 76" className="-rotate-90">
        <circle cx="38" cy="38" r={r} fill="none" stroke="rgb(var(--soft))" strokeWidth="8" />
        <circle
          cx="38" cy="38" r={r} fill="none" stroke="rgb(var(--brand))" strokeWidth="8" strokeLinecap="round"
          strokeDasharray={c} strokeDashoffset={c * (1 - done / total)}
          style={{ transition: 'stroke-dashoffset .6s cubic-bezier(.2,.8,.2,1)' }}
          className="motion-reduce:transition-none!"
        />
      </svg>
      <span className="absolute text-lg font-black tabular-nums">{done}/{total}</span>
    </div>
  );
}

export default function AdminStart() {
  const { me } = useAuth();
  const s = useStartSteps();
  const [busy, setBusy] = useState(false);

  const firstTodo = s.steps.find((x) => x.state !== 'done' && !s.skipped.includes(x.id));
  const allDone = !s.loading && s.doneCount === s.total;
  const left = s.steps.filter((x) => x.state !== 'done');

  const backup = async () => {
    setBusy(true);
    try {
      await downloadFile('/backup', 'coregsm-backup.tar.gz');
      toast(t('start.backupDone'));
    } catch (e) {
      fail(e);
    } finally {
      setBusy(false);
    }
  };

  const quick: { key: string; label: string; text: string; icon: ReactNode; href?: string; onClick?: () => void }[] = [
    { key: 'server', label: t('start.q.server'), text: t('start.q.server.t'), icon: <IconServers />, href: '/admin/servers/new' },
    { key: 'news', label: t('start.q.news'), text: t('start.q.news.t'), icon: <IconNews />, href: '/admin/news/new' },
    { key: 'backup', label: busy ? t('start.q.backupBusy') : t('start.q.backup'), text: t('start.q.backup.t'), icon: <IconDownload />, onClick: () => void backup() },
    { key: 'system', label: t('start.q.system'), text: t('start.q.system.t'), icon: <IconSystem />, href: '/admin/system' },
    { key: 'player', label: t('start.q.player'), text: t('start.q.player.t'), icon: <IconStart />, href: '/servers' },
  ];

  return (
    <AdminPage
      head={(
        <PageHead
          icon={<IconStart />}
          title={t('adm.s.start')}
          subtitle={me ? t('start.hello', { name: me.username }) : t('start.five')}
          hint={t('start.hint')}
          help={<p>{t('start.help')}</p>}
        />
      )}
    >

      {s.loading ? (
        <StartSkeleton />
      ) : (
        <>
          {allDone ? (
            <div className="tile fade-in flex flex-wrap items-center gap-4 p-5" role="status">
              <span className="pop relative grid h-14 w-14 shrink-0 place-items-center rounded-2xl bg-okbg text-ok"><Check size={30} /><Burst count={12} radius={38} /></span>
              <div className="min-w-0 flex-1 basis-60">
                <h2 className="text-xl font-extrabold leading-tight">{t('start.allDone')}</h2>
                <p className="font-semibold text-mute">{t('start.allDoneText')}</p>
              </div>
              <a className="btn" href="/admin/servers">{t('start.toServers')}</a>
            </div>
          ) : (
            <div className="tile flex flex-wrap items-center gap-4 p-5">
              <Ring done={s.doneCount} total={s.total} />
              <div className="min-w-0 flex-1 basis-60">
                <h2 className="text-xl font-extrabold leading-tight">{t('start.stepsDone', { a: s.doneCount, b: s.total })}</h2>
                <p className="font-semibold text-mute">
                  {left.length > 0 ? t('start.left', { list: left.map((x) => x.short).join(', ') }) : ''}
                </p>
              </div>
              {firstTodo && <a className="btn" href={firstTodo.href}>{t('start.continue')} {firstTodo.cta.toLowerCase()}</a>}
            </div>
          )}

          {/* finished steps are one folded line: they need no attention */}
          {s.doneCount > 0 && !allDone && (
            <details className="tile start-done group px-4 py-2.5 sm:px-5">
              <summary className="flex min-h-11 cursor-pointer list-none items-center gap-3 font-extrabold [&::-webkit-details-marker]:hidden">
                <span className="grid h-8 w-8 shrink-0 place-items-center rounded-xl bg-okbg text-ok"><Check size={18} /></span>
                <span className="min-w-0 flex-1">{t('start.doneGroup', { a: s.doneCount, b: s.total })}</span>
                <svg aria-hidden width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" className="shrink-0 text-mute transition-transform group-open:rotate-180"><path d="M6 9l6 6 6-6" /></svg>
              </summary>
              <ul className="mt-1 divide-y divide-line">
                {s.steps.filter((x) => x.state === 'done').map((st) => (
                  <li key={st.id} className="flex min-h-11 items-center justify-between gap-3 py-1.5">
                    <span className="min-w-0 truncate font-semibold text-mute">{st.title}</span>
                    <a className="btn btn-ghost btn-sm shrink-0" href={st.href}>{t('adm.open')}</a>
                  </li>
                ))}
              </ul>
            </details>
          )}

          <ol className="space-y-3" aria-label={t('start.stepsLabel')}>
            {s.steps.map((st, i) => {
              if (st.state === 'done' && !allDone) return null;
              const skipped = s.skipped.includes(st.id) && st.state !== 'done';
              const current = firstTodo?.id === st.id;
              return (
                <li key={st.id} className={`tile flex flex-wrap items-center gap-x-4 gap-y-3 p-4 sm:p-5 ${current ? 'ring-2 ring-brand/50' : ''}`}>
                  <span
                    className={`grid h-12 w-12 shrink-0 place-items-center rounded-2xl text-xl font-black ${
                      st.state === 'done' ? 'bg-okbg text-ok' : st.state === 'unknown' || skipped ? 'bg-soft text-mute' : 'bg-linear-to-br from-brand to-brand-2 text-white shadow-pop'
                    }`}
                    aria-hidden
                  >
                    {st.state === 'done' ? <Check /> : st.state === 'unknown' ? '?' : i + 1}
                  </span>
                  <div className="min-w-0 flex-1 basis-60">
                    <h3 className="flex flex-wrap items-center gap-2 font-extrabold leading-tight">
                      <span>{st.title}</span>
                      {st.state === 'done' && <span className="pill pill-ok">{t('start.pill.done')}</span>}
                      {st.state === 'unknown' && <span className="pill pill-mute">{t('start.pill.unknown')}</span>}
                      {skipped && <span className="pill pill-mute">{t('start.pill.skipped')}</span>}
                    </h3>
                    <p className="text-sm font-semibold text-mute">{st.why}</p>
                    {st.note && st.state !== 'done' && <p className="mt-1 text-sm font-bold text-warn">{st.note}</p>}
                  </div>
                  <div className="flex flex-wrap items-center gap-2 max-sm:w-full">
                    {/* the current step's action is the one big button above: no twin here */}
                    {!current && (
                      <a className={`btn ${st.state === 'unknown' ? '' : 'btn-soft'} ${st.state === 'done' ? 'btn-sm' : ''}`} href={st.href}>
                        {st.state === 'done' ? t('adm.open') : st.cta}
                      </a>
                    )}
                    {st.state !== 'done' && !skipped && (
                      <button type="button" className="btn btn-ghost btn-sm" onClick={() => s.skip(st.id)}>
                        {t('start.skip')}
                      </button>
                    )}
                    {skipped && (
                      <button type="button" className="btn btn-ghost btn-sm" onClick={() => s.unskip(st.id)}>
                        {t('start.unskip')}
                      </button>
                    )}
                  </div>
                </li>
              );
            })}
          </ol>
        </>
      )}

      {/* quick actions: open once everything is set up, folded while the checklist is still the main thing */}
      <details className="start-quick group" open={allDone || undefined}>
        <summary className="mb-3 flex min-h-11 cursor-pointer list-none items-center justify-between gap-3 [&::-webkit-details-marker]:hidden">
          <h2 id="start-quick" className="text-lg font-black">{t('start.quick')}</h2>
          <svg aria-hidden width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" className="shrink-0 text-mute transition-transform group-open:rotate-180"><path d="M6 9l6 6 6-6" /></svg>
        </summary>
        <div className="grid grid-cols-1 gap-3 min-[480px]:grid-cols-2 lg:grid-cols-3">
          {quick.map((q) => {
            const inner = (
              <>
                <span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-soft text-link">{q.icon}</span>
                <span className="min-w-0">
                  <span className="block font-extrabold leading-tight">{q.label}</span>
                  <span className="block text-sm font-semibold text-mute">{q.text}</span>
                </span>
              </>
            );
            const cls = 'tile tile-hover flex items-center gap-3 p-3.5 text-left';
            return q.href ? (
              <a key={q.key} className={cls} href={q.href}>{inner}</a>
            ) : (
              <button key={q.key} type="button" className={cls} onClick={q.onClick} disabled={busy}>{inner}</button>
            );
          })}
        </div>
      </details>

      <details className="tile start-map group p-5 sm:p-6">
        <summary className="flex cursor-pointer list-none items-center justify-between gap-3 [&::-webkit-details-marker]:hidden">
          <span>
            <span className="block text-lg font-black">{t('start.map')}</span>
            <span className="block font-semibold text-mute">{t('start.mapText')}</span>
          </span>
          <svg aria-hidden width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round" className="shrink-0 text-mute transition-transform group-open:rotate-180"><path d="M6 9l6 6 6-6" /></svg>
        </summary>
        <div className="mt-4 grid gap-x-8 gap-y-5 md:grid-cols-2">
          {ADMIN_GROUPS.map((g, gi) => (
            <div key={g.title}>
              <div className="adm-group-title px-0!">{g.title}</div>
              <ul className="space-y-1">
                {gi === 0 && <MapRow id={START_SECTION.id} label={START_SECTION.label} desc={START_SECTION.desc} icon={START_SECTION.icon()} />}
                {g.sections.map((sec) => <MapRow key={sec.id} id={sec.id} label={sec.label} desc={sec.desc} icon={sec.icon()} />)}
              </ul>
            </div>
          ))}
        </div>
      </details>
    </AdminPage>
  );
}

function MapRow({ id, label, desc, icon }: { id: string; label: string; desc: string; icon: ReactNode }) {
  return (
    <li>
      <a href={`/admin/${id}`} className="flex items-start gap-3 rounded-ui-lg px-2 py-2 transition hover:bg-soft">
        <span className="mt-0.5 grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-soft text-link">{icon}</span>
        <span className="min-w-0">
          <span className="block font-extrabold leading-tight">{label}</span>
          <span className="block text-sm font-semibold text-mute">{desc}</span>
        </span>
      </a>
    </li>
  );
}
__COREGSM_EOF__
  mkdir -p "$APP_DIR/core-frontend/src/pages"
  cat > "$APP_DIR/core-frontend/src/pages/Alerts.tsx" << '__COREGSM_EOF__'
import { useState } from 'react';
import { t, useI18n, type TKey } from '../i18n';
import AlertChannels from '../components/AlertChannels';
import DigestSection from '../components/DigestSection';
import { api, type SettingsInfo } from '../api';
import { ChannelName, ChannelPicker } from '../components/ChannelPicker';
import { AlertsArt } from '../components/Illustrations';
import { AdminPage, ErrorLine, GoLink, IconBell, LoadError, Notice, PageHead, Section, Switch, ago, toast, usePoll } from '../ui';

interface AlertsInfo {
  enabled: boolean;
  channelId: string;
  channelName: string | null;
  guildName: string | null;
  afterMin: number;
  mention: 'none' | 'here' | 'everyone';
  smart?: { low: boolean; ping: boolean; full: boolean };
  quiet?: { enabled: boolean; from: number; to: number; now: boolean };
  recent: { id: number; kind: keyof typeof KIND; serverName: string; status: string; error: string | null; createdAt: number; sentAt: number | null }[];
}

const KIND = {
  down: { label: 'al.k.down', cls: 'pill-bad' },
  up: { label: 'al.k.up', cls: 'pill-ok' },
  test: { label: 'al.k.test', cls: 'pill-mute' },
  low: { label: 'al.k.low', cls: 'pill-warn' },
  ping: { label: 'al.k.ping', cls: 'pill-warn' },
  full: { label: 'al.k.full', cls: 'pill-mute' },
  digest: { label: 'al.k.digest', cls: 'pill-ok' },
  restart: { label: 'al.k.restart', cls: 'pill-mute' },
  update: { label: 'al.k.update', cls: 'pill-ok' },
  disk: { label: 'al.k.disk', cls: 'pill-warn' },
  poll: { label: 'al.k.poll', cls: 'pill-ok' },
} as const satisfies Record<string, { label: TKey; cls: string }>;
/** a kind the panel does not know (a newer server, an old row) must not break the page */
const kindOf = (k: string): { label: TKey; cls: string } => (KIND as Record<string, { label: TKey; cls: string }>)[k] ?? KIND.test;

const SMART: { key: 'low' | 'ping' | 'full'; title: TKey; text: TKey }[] = [
  { key: 'low', title: 'al.s.low', text: 'al.s.lowText' },
  { key: 'ping', title: 'al.s.ping', text: 'al.s.pingText' },
  { key: 'full', title: 'al.s.full', text: 'al.s.fullText' },
];

/** what each kind of message looks like in the channel */
const SAMPLES: { kind: keyof typeof KIND; icon: string; text: TKey; on: (i: AlertsInfo) => boolean }[] = [
  { kind: 'down', icon: '🔴', text: 'al.m.down', on: (i) => i.enabled },
  { kind: 'up', icon: '🟢', text: 'al.m.up', on: (i) => i.enabled },
  { kind: 'low', icon: '📉', text: 'al.m.low', on: (i) => i.enabled && !!i.smart?.low },
  { kind: 'ping', icon: '📶', text: 'al.m.ping', on: (i) => i.enabled && !!i.smart?.ping },
  { kind: 'full', icon: '👥', text: 'al.m.full', on: (i) => i.enabled && !!i.smart?.full },
];

/** the cards of the message kinds: a sample line and whether the kind is on */
function KindCards({ info }: { info: AlertsInfo }) {
  const where = info.channelId ? (info.channelName ? `# ${info.channelName}` : t('al.where.channel', { id: info.channelId })) : t('al.where.none');
  return (
    <Section title={t('al.kinds')} description={t('al.kinds.text')}>
      <div className="al-kinds">
        {SAMPLES.map((x) => {
          const on = x.on(info);
          return (
            <div key={x.kind} className={`al-kind ${on ? '' : 'is-off'}`}>
              <div className="flex items-center gap-2"><span className={`pill ${KIND[x.kind].cls}`}>{t(KIND[x.kind].label)}</span><span className="ml-auto text-xs font-bold text-mute">{on ? t('al.on') : t('al.off')}</span></div>
              <p className="al-msg"><span aria-hidden>{x.icon}</span> {t(x.text)}</p>
              <p className="text-xs font-semibold text-mute">{where}</p>
            </div>
          );
        })}
      </div>
    </Section>
  );
}

const HOURS = Array.from({ length: 24 }, (_, h) => h);
const hh = (h: number) => `${String(h).padStart(2, '0')}:00`;

/** quiet hours: the messages keep coming, only without @here / @everyone */
function QuietHours({ info, save }: { info: AlertsInfo; save: (p: { quiet: { enabled: boolean; from: number; to: number } }, done?: string) => Promise<void> }) {
  const q = info.quiet ?? { enabled: false, from: 23, to: 8, now: false };
  const set = (patch: Partial<{ enabled: boolean; from: number; to: number }>) => void save({ quiet: { enabled: q.enabled, from: q.from, to: q.to, ...patch } });
  const span = q.from === q.to ? 0 : (q.to - q.from + 24) % 24;
  return (
    <Section title={t('al.q.title')} description={t('al.q.text')}>
      <label className="flex cursor-pointer items-center gap-3">
        <Switch checked={q.enabled} onChange={(on) => set({ enabled: on })} />
        <span className="font-extrabold">{t('al.q.noMention')}</span>
        {q.enabled && <span className={`pill ml-auto ${q.now ? 'pill-warn' : 'pill-mute'}`}>{q.now ? t('al.q.now') : t('al.q.normal')}</span>}
      </label>
      {q.enabled && (
        <div className="space-y-3">
          <div className="flex flex-wrap items-end gap-3">
            <div>
              <label htmlFor="quiet-from" className="label">{t('al.q.from')}</label>
              <select id="quiet-from" className="input" value={q.from} onChange={(e) => set({ from: Number(e.target.value) })}>{HOURS.map((h) => <option key={h} value={h}>{hh(h)}</option>)}</select>
            </div>
            <div>
              <label htmlFor="quiet-to" className="label">{t('al.q.to')}</label>
              <select id="quiet-to" className="input" value={q.to} onChange={(e) => set({ to: Number(e.target.value) })}>{HOURS.map((h) => <option key={h} value={h}>{hh(h)}</option>)}</select>
            </div>
            <p className="pb-2 text-sm font-semibold text-mute">{span === 0 ? t('al.q.same') : t('al.q.span', { n: span })}</p>
          </div>
          {/* the day at a glance: shaded cells are quiet */}
          <div className="qh-day" role="img" aria-label={t('al.q.aria', { a: hh(q.from), b: hh(q.to) })}>
            {HOURS.map((h) => {
              const quiet = span > 0 && (q.from < q.to ? h >= q.from && h < q.to : h >= q.from || h < q.to);
              return <span key={h} className={quiet ? 'is-quiet' : ''} title={`${hh(h)}${quiet ? t('al.q.quiet') : ''}`} />;
            })}
          </div>
          <div className="qh-ticks" aria-hidden><span>0</span><span>6</span><span>12</span><span>18</span><span>24</span></div>
        </div>
      )}
    </Section>
  );
}

/** the delivery queue in one line: how many left, are waiting, failed */
function Queue({ recent }: { recent: AlertsInfo['recent'] }) {
  const sent = recent.filter((r) => r.status === 'sent').length;
  const wait = recent.filter((r) => r.status === 'queued' || r.status === 'sending').length;
  const bad = recent.filter((r) => r.status === 'error').length;
  const pct = (n: number) => `${(n / recent.length) * 100}%`;
  return (
    <div className="space-y-1.5">
      <div className="al-queue" role="img" aria-label={t('al.queue.aria', { sent, wait, bad })}>
        <i className="is-ok" style={{ width: pct(sent) }} /><i className="is-warn" style={{ width: pct(wait) }} /><i className="is-bad" style={{ width: pct(bad) }} />
      </div>
      <p className="text-xs font-bold text-mute">{t('al.queue.line', { sent, wait, bad })}{bad > 0 ? t('al.queue.first') : ''}</p>
    </div>
  );
}

/** Messages to a Discord channel when a game server stops answering and when it is back. */
export default function AlertsPage() {
  useI18n();
  const [info, setInfo] = useState<AlertsInfo | null>(null);
  const [error, setError] = useState('');
  const [changing, setChanging] = useState(false);
  const [tokenSet, setTokenSet] = useState<boolean | null>(null);

  const load = () => {
    api<SettingsInfo>('/settings').then((s) => setTokenSet(s.discordTokenSet)).catch(() => undefined);
    return api<AlertsInfo>('/alerts').then((a) => { setInfo(a); setError(''); }).catch((e: Error) => setError(e.message));
  };
  usePoll(load, 10_000);

  const save = async (patch: Partial<Pick<AlertsInfo, 'enabled' | 'channelId' | 'afterMin' | 'mention' | 'smart'>> & { quiet?: { enabled: boolean; from: number; to: number } }, done?: string) => {
    await api<AlertsInfo>('/alerts', 'PUT', patch)
      .then((a) => { setInfo(a); setError(''); if (done) toast(done); })
      .catch((e: Error) => setError(e.message));
  };
  const test = async () => {
    await api<AlertsInfo>('/alerts/test', 'POST').then((a) => { setInfo(a); toast(t('al.test.done')); }).catch((e: Error) => setError(e.message));
  };

  return (
    <AdminPage
      narrow
      head={(
        <PageHead
          icon={<IconBell />}
          title={t('al.title')}
          subtitle={t('al.sub')}
          hint={t('al.hint')}
          help={<p>{t('al.help')}</p>}
        >
          <button className="btn btn-soft" onClick={() => void test()} disabled={!info?.channelId}>{t('al.sendTest')}</button>
        </PageHead>
      )}
    >
      {error && !info ? <LoadError error={error} onRetry={() => void load()} /> : <ErrorLine text={error} />}
      {tokenSet === false && (
        <Notice action={<GoLink href="/admin/settings/bot">{t('al.noToken')}</GoLink>}>
          {t('al.noTokenText')}
        </Notice>
      )}

      {info && (
        <Section>
          <label className="flex cursor-pointer items-start gap-3">
            <Switch className="mt-0.5" checked={info.enabled} onChange={(on) => void save({ enabled: on }, on ? t('al.on.done') : t('al.off.done'))} />
            <span>
              <span className="block font-extrabold">{t('al.enable')}</span>
              <span className="block text-sm font-semibold text-mute">{t('al.enableText')}</span>
            </span>
          </label>

          <div>
            <span className="label">{t('al.channel')}</span>
            <div className="flex flex-wrap items-center gap-3">
              <span className="font-black">{info.channelId ? (info.channelName ? `# ${info.channelName}${info.guildName ? ` · ${info.guildName}` : ''}` : <ChannelName id={info.channelId} />) : t('al.channel.none')}</span>
              <button className="btn btn-soft btn-sm" onClick={() => setChanging((v) => !v)} aria-expanded={changing}>{info.channelId ? t('al.change') : t('al.pick')}</button>
            </div>
            {changing && (
              <div className="mt-3">
                <ChannelPicker id="alerts-channel" value={info.channelId} onChange={(v) => { if (/^\d{15,25}$/.test(v)) { void save({ channelId: v }, t('al.channel.saved')); setChanging(false); } }} />
              </div>
            )}
          </div>

          <div className="grid gap-4 sm:grid-cols-2">
            <div>
              <label htmlFor="alerts-after" className="label">{t('al.after')}</label>
              <select id="alerts-after" className="input" value={info.afterMin} onChange={(e) => void save({ afterMin: Number(e.target.value) }, t('al.saved'))}>
                {[1, 2, 3, 5, 10, 15, 30, 60].map((m) => <option key={m} value={m}>{t('al.after.n', { n: m })}</option>)}
              </select>
              <p className="mt-1 text-sm font-semibold text-mute">{t('al.afterText')}</p>
            </div>
            <div>
              <label htmlFor="alerts-mention" className="label">{t('al.mention')}</label>
              <select id="alerts-mention" className="input" value={info.mention} onChange={(e) => void save({ mention: e.target.value as AlertsInfo['mention'] }, t('al.saved'))}>
                <option value="none">{t('al.mention.none')}</option>
                <option value="here">{t('al.mention.here')}</option>
                <option value="everyone">@everyone</option>
              </select>
              <p className="mt-1 text-sm font-semibold text-mute">{t('al.mentionText')}</p>
            </div>
          </div>
        </Section>
      )}

      {info && (
        <Section title={t('al.smart')} description={t('al.smartText')}>
          {SMART.map((r) => (
            <label key={r.key} className="flex cursor-pointer items-start gap-3">
              <Switch className="mt-0.5" checked={!!info.smart?.[r.key]} disabled={!info.enabled} onChange={(on) => void save({ smart: { ...(info.smart ?? { low: false, ping: false, full: false }), [r.key]: on } }, on ? t('al.smart.on') : t('al.smart.off'))} />
              <span>
                <span className="block font-extrabold">{t(r.title)}</span>
                <span className="block text-sm font-semibold text-mute">{t(r.text)}</span>
              </span>
            </label>
          ))}
          {!info.enabled && <p className="text-sm font-semibold text-mute">{t('al.smart.first')}</p>}
        </Section>
      )}

      {info && <KindCards info={info} />}

      {info && <QuietHours info={info} save={save} />}

      <AlertChannels />

      <DigestSection alertsChannel={info?.channelId ?? ''} />

      <Section title={t('al.recent')}>
        {!info && <div className="skeleton h-14 rounded-ui-lg" aria-busy="true" aria-label={t('al.loading')} />}
        {info && info.recent.length === 0 && (
          <div className="fade-in flex flex-col items-center gap-1 py-2 text-center">
            <AlertsArt />
            <p className="font-extrabold">{t('al.none')}</p>
            <p className="max-w-sm text-sm font-semibold text-mute">
              {info.channelId ? t('al.none.ch') : t('al.none.noCh')}
            </p>
            {!info.channelId && <button className="btn mt-2" onClick={() => setChanging(true)}>{t('al.pick')}</button>}
          </div>
        )}
        {info && info.recent.length > 0 && <Queue recent={info.recent} />}
        <ul className="divide-y divide-line">
          {info && [...info.recent].sort((a, b) => Number(b.status === 'error') - Number(a.status === 'error')).map((r) => (
            <li key={r.id} className="flex flex-wrap items-center gap-x-3 gap-y-1 py-2.5">
              <span className={`pill ${kindOf(r.kind).cls}`}>{t(kindOf(r.kind).label)}</span>
              <span className="min-w-0 flex-1 truncate font-bold">{r.serverName}</span>
              {r.status === 'sent' && <span className="text-sm font-semibold text-mute">{t('al.sent', { ago: ago(r.sentAt) })}</span>}
              {(r.status === 'queued' || r.status === 'sending') && <span className="text-sm font-semibold text-warn">{t('al.waits')}</span>}
              {r.status === 'error' && <span className="text-sm font-bold text-bad" title={r.error ?? ''}>{t('al.failed', { e: r.error ?? '' })}</span>}
            </li>
          ))}
        </ul>
      </Section>
    </AdminPage>
  );
}
