    expect(moveId([1, 2], [1, 2], 2, 1)).toBeNull();
  });
  it('works among a subset of the list', () => {
    expect(moveId([1, 2, 3, 4], [2, 4], 4, -1)).toEqual([1, 4, 3, 2]);
  });
});

